# ---- embedded module: stitch_new_uav.py ----
base_namespace = {"__name__": "_base", "__file__": _embedded_file}
sys.modules["_base"] = SimpleNamespace(**base_namespace)
exec(compile('#!/usr/bin/env python3\n"""Stitch the four-camera panorama for the new UAV configuration.\n\nThis script is intentionally independent from the legacy panorama pipeline.  It\nuses the new-UAV Kalibr files directly, so the topic-to-camera mapping, camera\nmodel and transform direction cannot silently fall back to the old UAV setup.\n\nDefault input:\n    202605_hangzhou/north_square/new_uav\n\nDefault output:\n    output_panos/202605_hangzhou/north_square/new_uav/corrected\n\nExamples:\n    # Estimate a stitching-specific rotation refinement once for this rig.\n    python stitch_new_uav.py --estimate-refinement\n\n    # Stitch one frame nearest to a timestamp and save per-camera debug warps.\n    python stitch_new_uav.py --timestamp 1778833523.663248 --debug\n\n    # Stitch the first 100 synchronized frames, sampling every fifth frame.\n    python stitch_new_uav.py --max-frames 100 --stride 5\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport math\nimport re\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom typing import Dict, Iterable, List, Mapping, Optional, Tuple\n\nimport cv2\nimport numpy as np\nimport yaml\n\n\nSCRIPT_DIR = Path(__file__).resolve().parent\nPROJECT_ROOT = SCRIPT_DIR.parent\n\nDEFAULT_INPUT_DIR = PROJECT_ROOT / "202605_hangzhou/north_square/new_uav"\nDEFAULT_CALIB_DIR = SCRIPT_DIR / "cam-to-imu"\nDEFAULT_OUTPUT_DIR = (\n    PROJECT_ROOT / "output_panos/202605_hangzhou/north_square/new_uav/corrected"\n)\nDEFAULT_REFINEMENT_PATH = SCRIPT_DIR / "image_alignment_refinement.json"\n\nPANO_WIDTH = 1280\nPANO_HEIGHT = 640\nVERTICAL_FOV_DEG = 130.0\nSPHERE_RADIUS_M = 30.0\n# Fraction of the inscribed image radius considered optically valid.  The\n# default preserves the historical behaviour; specialized stitchers may use a\n# tighter value to exclude a visible fisheye housing/rim.\nFISHEYE_VALID_RADIUS_SCALE = 0.98\n\n\n# New-UAV wiring/mounting relationship.  This differs from the legacy UAV.\nTOPIC_TO_CAMERA = {\n    "left": "left_front",\n    "bleft": "right_front",\n    "right": "right_back",\n    "bright": "left_back",\n}\nTOPIC_NAMES = frozenset(TOPIC_TO_CAMERA)\n\nCAMERA_TO_YAML = {\n    "left_front": "left_cam_IMU_kalibr_new-camchain-imucam.yaml",\n    "right_front": "bleft_cam_IMU_kalibr_new_bag-camchain-imucam.yaml",\n    "right_back": "right_cam_IMU_kalibr_new-camchain-imucam.yaml",\n    "left_back": "bright_cam_IMU_kalibr_new-camchain-imucam.yaml",\n}\n\n# Physical order around the airframe.  The blend itself is order-independent,\n# but a stable order makes debug output and diagnostics easier to understand.\nCAMERA_ORDER = ("left_front", "right_front", "right_back", "left_back")\nBASE_CAMERA = "left_front"\nADJACENT_CAMERA_PAIRS = (\n    ("left_front", "right_front"),\n    ("right_front", "right_back"),\n    ("right_back", "left_back"),\n    ("left_back", "left_front"),\n)\n\n\n@dataclass(frozen=True)\nclass CameraCalibration:\n    K: np.ndarray\n    D: np.ndarray\n    T_cam_imu: np.ndarray\n    resolution: Tuple[int, int]\n\n\n@dataclass(frozen=True)\nclass SynchronizedFrame:\n    timestamp: float\n    files: Mapping[str, Path]\n    max_sync_gap: float\n\n\ndef parse_timestamp(path: Path) -> float:\n    """Parse ROS-style seconds or seconds_nanoseconds from an image name."""\n    stem = path.stem\n    # Some recordings use Unix epoch seconds while others use a shorter\n    # ROS/steady-clock counter such as 524432.070537.\n    match = re.search(r"(?:^|_)(\\d+\\.\\d+)$", stem)\n    if match:\n        return float(match.group(1))\n\n    match = re.search(r"(?:^|_)(\\d+)_(\\d+)$", stem)\n    if match:\n        seconds = int(match.group(1))\n        nanoseconds = int(match.group(2)) % 1_000_000_000\n        return seconds + nanoseconds * 1e-9\n\n    raise ValueError(f"Cannot parse timestamp from {path.name}")\n\n\ndef load_calibration(path: Path) -> CameraCalibration:\n    with path.open("r", encoding="utf-8") as handle:\n        data = yaml.safe_load(handle)["cam0"]\n\n    if data.get("camera_model") != "pinhole":\n        raise ValueError(f"{path}: expected Kalibr pinhole camera model")\n    if data.get("distortion_model") != "equidistant":\n        raise ValueError(f"{path}: expected Kalibr equidistant distortion model")\n\n    fx, fy, cx, cy = (float(value) for value in data["intrinsics"])\n    K = np.array([[fx, 0.0, cx], [0.0, fy, cy], [0.0, 0.0, 1.0]])\n    D = np.asarray(data["distortion_coeffs"], dtype=np.float64)\n\n    rows = data["T_cam_imu"]\n    # Be tolerant of a historical malformed fifth element in a YAML row.\n    T_cam_imu = np.asarray([row[:4] for row in rows], dtype=np.float64)\n    if T_cam_imu.shape != (4, 4):\n        raise ValueError(f"{path}: T_cam_imu must be 4x4")\n\n    resolution = tuple(int(value) for value in data["resolution"])\n    return CameraCalibration(K=K, D=D, T_cam_imu=T_cam_imu, resolution=resolution)\n\n\ndef load_all_calibrations(calib_dir: Path) -> Dict[str, CameraCalibration]:\n    calibrations = {}\n    for camera, filename in CAMERA_TO_YAML.items():\n        path = calib_dir / filename\n        if not path.is_file():\n            raise FileNotFoundError(f"Missing new-UAV calibration: {path}")\n        calibrations[camera] = load_calibration(path)\n    return calibrations\n\n\ndef _normalize_camera_name(value: str) -> str:\n    return re.sub(r"[\\s-]+", "_", value.strip().lower())\n\n\ndef load_topic_to_camera(path: Optional[Path]) -> Dict[str, str]:\n    """Load an optional ``topic -> logical_camera`` text mapping.\n\n    The logical names are the physical panorama positions used by the\n    calibration/refinement (left_front, right_front, right_back, left_back).\n    Keeping this mapping outside the calibration lets recordings with changed\n    ROS wiring reuse the same physical rig calibration.\n    """\n    if path is None:\n        return dict(TOPIC_TO_CAMERA)\n    if not path.is_file():\n        raise FileNotFoundError(f"Missing camera mapping: {path}")\n\n    mapping: Dict[str, str] = {}\n    for line_number, raw_line in enumerate(\n        path.read_text(encoding="utf-8").splitlines(), start=1\n    ):\n        line = raw_line.split("#", 1)[0].strip()\n        if not line:\n            continue\n        if "->" not in line:\n            raise ValueError(f"{path}:{line_number}: expected \'topic -> camera\'")\n        topic_text, camera_text = line.split("->", 1)\n        topic = topic_text.strip().lower()\n        camera = _normalize_camera_name(camera_text)\n        if topic in mapping:\n            raise ValueError(f"{path}:{line_number}: duplicate topic {topic!r}")\n        mapping[topic] = camera\n\n    expected_cameras = set(CAMERA_ORDER)\n    if set(mapping) != set(TOPIC_NAMES):\n        raise ValueError(\n            f"{path}: topics must be exactly {sorted(TOPIC_NAMES)}, "\n            f"got {sorted(mapping)}"\n        )\n    if set(mapping.values()) != expected_cameras or len(set(mapping.values())) != 4:\n        raise ValueError(\n            f"{path}: camera values must be a one-to-one mapping of "\n            f"{sorted(expected_cameras)}, got {sorted(mapping.values())}"\n        )\n    return mapping\n\n\ndef build_image_indices(\n    input_dir: Path,\n    topic_to_camera: Optional[Mapping[str, str]] = None,\n) -> Dict[str, List[Tuple[float, Path]]]:\n    topic_to_camera = topic_to_camera or TOPIC_TO_CAMERA\n    indices: Dict[str, List[Tuple[float, Path]]] = {}\n    for topic, camera in topic_to_camera.items():\n        candidates = (\n            input_dir / f"fisheye_{topic}_image_raw_compress_compressed",\n            input_dir / f"fisheye_{topic}_image_raw",\n        )\n        directory = next((candidate for candidate in candidates if candidate.is_dir()), None)\n        if directory is None:\n            raise FileNotFoundError(\n                "Missing image directory; tried: "\n                + ", ".join(str(candidate) for candidate in candidates)\n            )\n\n        frames = []\n        for path in directory.iterdir():\n            if path.suffix.lower() not in {".jpg", ".jpeg", ".png"}:\n                continue\n            if path.stat().st_size == 0:\n                continue\n            try:\n                frames.append((parse_timestamp(path), path))\n            except ValueError:\n                continue\n        frames.sort(key=lambda item: item[0])\n        if not frames:\n            raise RuntimeError(f"No timestamped images found in {directory}")\n        indices[camera] = frames\n    return indices\n\n\ndef nearest_frame(\n    frames: List[Tuple[float, Path]], target: float\n) -> Tuple[float, Path]:\n    timestamps = np.fromiter((item[0] for item in frames), dtype=np.float64)\n    index = int(np.searchsorted(timestamps, target))\n    candidates = []\n    if index < len(frames):\n        candidates.append(frames[index])\n    if index > 0:\n        candidates.append(frames[index - 1])\n    return min(candidates, key=lambda item: abs(item[0] - target))\n\n\ndef synchronize_frames(\n    indices: Mapping[str, List[Tuple[float, Path]]], max_sync_gap: float\n) -> List[SynchronizedFrame]:\n    synchronized = []\n    # Anchor synchronization on the sparsest stream so one high-rate camera\n    # cannot create duplicate four-camera groups by reusing a slower frame.\n    sync_camera = min(CAMERA_ORDER, key=lambda camera: len(indices[camera]))\n    for timestamp, base_path in indices[sync_camera]:\n        files: Dict[str, Path] = {sync_camera: base_path}\n        largest_gap = 0.0\n        valid = True\n        for camera in CAMERA_ORDER:\n            if camera == sync_camera:\n                continue\n            other_timestamp, other_path = nearest_frame(indices[camera], timestamp)\n            gap = abs(other_timestamp - timestamp)\n            if gap > max_sync_gap:\n                valid = False\n                break\n            files[camera] = other_path\n            largest_gap = max(largest_gap, gap)\n        if valid:\n            synchronized.append(\n                SynchronizedFrame(timestamp, files, largest_gap)\n            )\n    return synchronized\n\n\ndef _fit_rotation(source_rays: np.ndarray, target_rays: np.ndarray) -> np.ndarray:\n    """Kabsch rotation mapping source unit rays into target unit rays."""\n    covariance = source_rays.T @ target_rays\n    left, _, right_t = np.linalg.svd(covariance)\n    rotation = right_t.T @ left.T\n    if np.linalg.det(rotation) < 0.0:\n        right_t[-1, :] *= -1.0\n        rotation = right_t.T @ left.T\n    return rotation\n\n\ndef _rotation_errors_deg(\n    rotation: np.ndarray, source_rays: np.ndarray, target_rays: np.ndarray\n) -> np.ndarray:\n    predicted = (rotation @ source_rays.T).T\n    cosine = np.sum(predicted * target_rays, axis=1)\n    return np.rad2deg(np.arccos(np.clip(cosine, -1.0, 1.0)))\n\n\ndef estimate_rotation_ransac(\n    source_rays: np.ndarray,\n    target_rays: np.ndarray,\n    threshold_deg: float = 1.5,\n    iterations: int = 2500,\n) -> Tuple[np.ndarray, np.ndarray, float]:\n    if len(source_rays) < 12:\n        raise RuntimeError("Too few bearing correspondences for rotation fitting")\n\n    generator = np.random.default_rng(20260715)\n    best_inliers = np.zeros(len(source_rays), dtype=bool)\n    for _ in range(iterations):\n        sample = generator.choice(len(source_rays), size=3, replace=False)\n        rotation = _fit_rotation(source_rays[sample], target_rays[sample])\n        inliers = (\n            _rotation_errors_deg(rotation, source_rays, target_rays)\n            < threshold_deg\n        )\n        if int(np.count_nonzero(inliers)) > int(np.count_nonzero(best_inliers)):\n            best_inliers = inliers\n\n    if int(np.count_nonzero(best_inliers)) < 10:\n        raise RuntimeError("Rotation RANSAC did not find a stable consensus")\n\n    for _ in range(3):\n        rotation = _fit_rotation(\n            source_rays[best_inliers], target_rays[best_inliers]\n        )\n        errors = _rotation_errors_deg(rotation, source_rays, target_rays)\n        best_inliers = errors < threshold_deg\n\n    median_error = float(np.median(errors[best_inliers]))\n    return rotation, best_inliers, median_error\n\n\ndef _unit_rays_from_keypoints(\n    points: np.ndarray, calibration: CameraCalibration\n) -> np.ndarray:\n    normalized = cv2.fisheye.undistortPoints(\n        points.reshape(-1, 1, 2).astype(np.float64),\n        calibration.K,\n        calibration.D,\n    ).reshape(-1, 2)\n    rays = np.column_stack(\n        (normalized[:, 0], normalized[:, 1], np.ones(len(normalized)))\n    )\n    rays /= np.linalg.norm(rays, axis=1, keepdims=True)\n    return rays\n\n\ndef _match_raw_frame_bearings(\n    frame: SynchronizedFrame,\n    calibrations: Mapping[str, CameraCalibration],\n    sift,\n    matcher,\n) -> Dict[Tuple[str, str], Tuple[np.ndarray, np.ndarray]]:\n    features = {}\n    for camera in CAMERA_ORDER:\n        image = cv2.imread(str(frame.files[camera]), cv2.IMREAD_GRAYSCALE)\n        if image is None:\n            raise RuntimeError(f"Cannot read image: {frame.files[camera]}")\n        calibration = calibrations[camera]\n        center = (\n            int(round(calibration.K[0, 2])),\n            int(round(calibration.K[1, 2])),\n        )\n        width, height = calibration.resolution\n        radius = int(\n            min(\n                center[0],\n                width - 1 - center[0],\n                center[1],\n                height - 1 - center[1],\n            )\n            * 0.97\n        )\n        mask = np.zeros_like(image)\n        cv2.circle(mask, center, radius, 255, thickness=-1)\n        keypoints, descriptors = sift.detectAndCompute(image, mask)\n        features[camera] = (keypoints, descriptors)\n\n    matched = {}\n    for first_camera, second_camera in ADJACENT_CAMERA_PAIRS:\n        first_keypoints, first_descriptors = features[first_camera]\n        second_keypoints, second_descriptors = features[second_camera]\n        if first_descriptors is None or second_descriptors is None:\n            continue\n\n        forward = matcher.knnMatch(first_descriptors, second_descriptors, k=2)\n        reverse = matcher.knnMatch(second_descriptors, first_descriptors, k=2)\n        forward_good = {\n            matches[0].queryIdx: matches[0].trainIdx\n            for matches in forward\n            if len(matches) == 2\n            and matches[0].distance < 0.72 * matches[1].distance\n        }\n        reverse_good = {\n            matches[0].queryIdx: matches[0].trainIdx\n            for matches in reverse\n            if len(matches) == 2\n            and matches[0].distance < 0.72 * matches[1].distance\n        }\n        mutual = [\n            (first_index, second_index)\n            for first_index, second_index in forward_good.items()\n            if reverse_good.get(second_index) == first_index\n        ]\n        if len(mutual) < 8:\n            continue\n\n        first_points = np.asarray(\n            [first_keypoints[i].pt for i, _ in mutual], dtype=np.float64\n        )\n        second_points = np.asarray(\n            [second_keypoints[j].pt for _, j in mutual], dtype=np.float64\n        )\n        matched[(first_camera, second_camera)] = (\n            _unit_rays_from_keypoints(\n                first_points, calibrations[first_camera]\n            ),\n            _unit_rays_from_keypoints(\n                second_points, calibrations[second_camera]\n            ),\n        )\n    return matched\n\n\ndef select_refinement_frames(\n    frames: List[SynchronizedFrame], count: int, trim_seconds: float\n) -> List[SynchronizedFrame]:\n    start = frames[0].timestamp + trim_seconds\n    end = frames[-1].timestamp - trim_seconds\n    candidates = [frame for frame in frames if start <= frame.timestamp <= end]\n    if len(candidates) < count:\n        raise RuntimeError(\n            f"Only {len(candidates)} frames remain after trimming; need {count}"\n        )\n    indices = np.linspace(0, len(candidates) - 1, count, dtype=int)\n    return [candidates[index] for index in indices]\n\n\ndef estimate_image_alignment_refinement(\n    frames: List[SynchronizedFrame],\n    calibrations: Mapping[str, CameraCalibration],\n    output_path: Path,\n    frame_count: int,\n    trim_seconds: float,\n) -> None:\n    try:\n        from scipy.optimize import least_squares\n        from scipy.spatial.transform import Rotation\n    except ImportError as exc:\n        raise RuntimeError(\n            "Alignment estimation requires scipy in the active Python environment"\n        ) from exc\n\n    selected = select_refinement_frames(frames, frame_count, trim_seconds)\n    sift = cv2.SIFT_create(nfeatures=8000, contrastThreshold=0.02)\n    matcher = cv2.BFMatcher(cv2.NORM_L2)\n    accumulated = {pair: [[], []] for pair in ADJACENT_CAMERA_PAIRS}\n\n    for index, frame in enumerate(selected, start=1):\n        matches = _match_raw_frame_bearings(\n            frame, calibrations, sift, matcher\n        )\n        for pair, (first_rays, second_rays) in matches.items():\n            accumulated[pair][0].append(first_rays)\n            accumulated[pair][1].append(second_rays)\n        print(\n            f"[refine {index}/{len(selected)}] {frame.timestamp:.6f}: "\n            + ", ".join(\n                f"{a}->{b}={len(matches.get((a, b), ([], []))[0])}"\n                for a, b in ADJACENT_CAMERA_PAIRS\n            )\n        )\n\n    edges = []\n    edge_report = {}\n    for pair in ADJACENT_CAMERA_PAIRS:\n        if not accumulated[pair][0]:\n            raise RuntimeError(f"No matches accumulated for {pair}")\n        source = np.concatenate(accumulated[pair][0], axis=0)\n        target = np.concatenate(accumulated[pair][1], axis=0)\n        rotation, inliers, median_error = estimate_rotation_ransac(source, target)\n        inlier_count = int(np.count_nonzero(inliers))\n        edges.append((pair[0], pair[1], rotation, inlier_count))\n        edge_report[f"{pair[0]}_to_{pair[1]}"] = {\n            "matches": int(len(source)),\n            "inliers": inlier_count,\n            "median_angular_error_deg": median_error,\n            "R_second_from_first": rotation.tolist(),\n        }\n        print(\n            f"[pair] {pair[0]} -> {pair[1]}: "\n            f"{inlier_count}/{len(source)} inliers, "\n            f"median {median_error:.3f} deg"\n        )\n\n    variable_cameras = [camera for camera in CAMERA_ORDER if camera != BASE_CAMERA]\n    camera_to_slice = {\n        camera: slice(index * 3, index * 3 + 3)\n        for index, camera in enumerate(variable_cameras)\n    }\n    base_rotation_imu = calibrations[BASE_CAMERA].T_cam_imu[:3, :3]\n    initial = np.zeros(len(variable_cameras) * 3, dtype=np.float64)\n    for camera in variable_cameras:\n        relative = (\n            calibrations[camera].T_cam_imu[:3, :3]\n            @ base_rotation_imu.T\n        )\n        initial[camera_to_slice[camera]] = Rotation.from_matrix(\n            relative\n        ).as_rotvec()\n\n    def unpack(parameters):\n        rotations = {BASE_CAMERA: np.eye(3)}\n        for camera in variable_cameras:\n            rotations[camera] = Rotation.from_rotvec(\n                parameters[camera_to_slice[camera]]\n            ).as_matrix()\n        return rotations\n\n    def residual(parameters):\n        rotations = unpack(parameters)\n        errors = []\n        for first, second, measured, inlier_count in edges:\n            predicted = rotations[second] @ rotations[first].T\n            error = Rotation.from_matrix(measured.T @ predicted).as_rotvec()\n            weight = math.sqrt(min(inlier_count, 250) / 100.0)\n            errors.extend(error * weight)\n        return np.asarray(errors)\n\n    optimized = least_squares(\n        residual,\n        initial,\n        loss="soft_l1",\n        f_scale=np.deg2rad(0.5),\n        max_nfev=1000,\n    )\n    rotations = unpack(optimized.x)\n\n    # Keep the camera centers from Kalibr, but express them in the base camera\n    # frame.  Image matching refines orientation only; translation is weakly\n    # observable in distant aerial imagery.\n    base_transform = calibrations[BASE_CAMERA].T_cam_imu\n    base_center_imu = -base_transform[:3, :3].T @ base_transform[:3, 3]\n    refinement = {}\n    for camera in CAMERA_ORDER:\n        transform = calibrations[camera].T_cam_imu\n        center_imu = -transform[:3, :3].T @ transform[:3, 3]\n        center_base = base_rotation_imu @ (center_imu - base_center_imu)\n        refinement[camera] = {\n            "R_base_to_cam": rotations[camera].tolist(),\n            "camera_center_in_base_m": center_base.tolist(),\n        }\n\n    payload = {\n        "description": "New-UAV image-based rotation refinement",\n        "base_camera": BASE_CAMERA,\n        "source_frame_timestamps": [frame.timestamp for frame in selected],\n        "pairwise_diagnostics": edge_report,\n        "cameras": refinement,\n    }\n    output_path.parent.mkdir(parents=True, exist_ok=True)\n    with output_path.open("w", encoding="utf-8") as handle:\n        json.dump(payload, handle, indent=2)\n    print(f"Saved image alignment refinement to {output_path}")\n\n\ndef spherical_points() -> np.ndarray:\n    theta = np.linspace(-np.pi, np.pi, PANO_WIDTH, endpoint=False)\n    vertical_fov = np.deg2rad(VERTICAL_FOV_DEG)\n    phi = np.linspace(-vertical_fov / 2.0, vertical_fov / 2.0, PANO_HEIGHT)\n    theta_map, phi_map = np.meshgrid(theta, phi)\n\n    x = SPHERE_RADIUS_M * np.cos(phi_map) * np.sin(theta_map)\n    y = SPHERE_RADIUS_M * np.sin(phi_map)\n    z = SPHERE_RADIUS_M * np.cos(phi_map) * np.cos(theta_map)\n    return np.stack((x, y, z), axis=-1).reshape(-1, 3)\n\n\ndef project_equidistant(\n    points_cam: np.ndarray, K: np.ndarray, D: np.ndarray\n) -> np.ndarray:\n    x, y, z = points_cam.T\n    radial = np.hypot(x, y)\n    theta = np.arctan2(radial, z)\n    theta2 = theta * theta\n    k1, k2, k3, k4 = D\n    theta_distorted = theta * (\n        1.0\n        + k1 * theta2\n        + k2 * theta2**2\n        + k3 * theta2**3\n        + k4 * theta2**4\n    )\n    scale = np.divide(\n        theta_distorted,\n        radial,\n        out=np.ones_like(theta_distorted),\n        where=radial > 1e-10,\n    )\n    u = K[0, 0] * x * scale + K[0, 2]\n    v = K[1, 1] * y * scale + K[1, 2]\n    return np.stack((u, v), axis=-1)\n\n\ndef make_lut(\n    points_base: np.ndarray,\n    calibration: CameraCalibration,\n    T_base_to_cam: np.ndarray,\n) -> Tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray]:\n    points_cam = (\n        T_base_to_cam[:3, :3] @ points_base.T\n    ).T + T_base_to_cam[:3, 3]\n    uv = project_equidistant(points_cam, calibration.K, calibration.D)\n    uv = uv.reshape(PANO_HEIGHT, PANO_WIDTH, 2).astype(np.float32)\n    map_x, map_y = uv[..., 0], uv[..., 1]\n\n    width, height = calibration.resolution\n    cx, cy = calibration.K[0, 2], calibration.K[1, 2]\n    radius = (\n        min(cx, width - 1 - cx, cy, height - 1 - cy)\n        * FISHEYE_VALID_RADIUS_SCALE\n    )\n    pixel_radius = np.hypot(map_x - cx, map_y - cy)\n    valid = (\n        (points_cam[:, 2].reshape(PANO_HEIGHT, PANO_WIDTH) > 0.0)\n        & (map_x >= 0.0)\n        & (map_x < width - 1)\n        & (map_y >= 0.0)\n        & (map_y < height - 1)\n        & (pixel_radius <= radius)\n    )\n    mask = (valid.astype(np.uint8) * 255)\n    # Prefer the camera whose optical axis is closest to the panorama ray.\n    # This confidence is used to choose a narrow seam instead of averaging a\n    # very wide overlap, which produces transparent double images under\n    # unavoidable multi-camera parallax.\n    point_norm = np.linalg.norm(points_cam, axis=1)\n    confidence = np.divide(\n        points_cam[:, 2],\n        point_norm,\n        out=np.full_like(point_norm, -1.0),\n        where=point_norm > 1e-10,\n    ).reshape(PANO_HEIGHT, PANO_WIDTH)\n    confidence = confidence.astype(np.float32)\n    confidence[~valid] = -1.0\n    return map_x, map_y, mask, confidence\n\n\ndef _horizontal_wrap_blur(image: np.ndarray, sigma: float) -> np.ndarray:\n    if sigma <= 0.0:\n        return image.astype(np.float32)\n    padding = max(1, int(np.ceil(3.0 * sigma)))\n    extended = np.concatenate(\n        (image[:, -padding:], image, image[:, :padding]), axis=1\n    )\n    blurred = cv2.GaussianBlur(\n        extended,\n        (0, 0),\n        sigmaX=sigma,\n        sigmaY=sigma,\n        borderType=cv2.BORDER_REPLICATE,\n    )\n    return blurred[:, padding:-padding]\n\n\ndef seam_blend(\n    warped_images: Iterable[np.ndarray],\n    warped_masks: Iterable[np.ndarray],\n    confidences: Iterable[np.ndarray],\n    seam_feather_px: float,\n) -> np.ndarray:\n    images = list(warped_images)\n    masks = list(warped_masks)\n    confidence_stack = np.stack(list(confidences), axis=0)\n    valid_stack = np.stack([mask > 0 for mask in masks], axis=0)\n    confidence_stack = np.where(valid_stack, confidence_stack, -np.inf)\n    coverage = np.any(valid_stack, axis=0)\n    winner = np.argmax(confidence_stack, axis=0)\n\n    canvas = np.zeros((PANO_HEIGHT, PANO_WIDTH, 3), dtype=np.float32)\n    total_weight = np.zeros((PANO_HEIGHT, PANO_WIDTH, 1), dtype=np.float32)\n\n    for camera_index, (image, mask) in enumerate(zip(images, masks)):\n        hard_seam = ((winner == camera_index) & coverage).astype(np.float32)\n        weight = _horizontal_wrap_blur(hard_seam, seam_feather_px)\n        weight *= (mask > 0).astype(np.float32)\n        weight = weight[..., None]\n        canvas += image.astype(np.float32) * weight\n        total_weight += weight\n\n    result = np.zeros_like(canvas)\n    np.divide(canvas, total_weight, out=result, where=total_weight > 1e-6)\n    return np.clip(result, 0, 255).astype(np.uint8)\n\n\ndef compensate_exposure(\n    warped_images: Mapping[str, np.ndarray],\n    warped_masks: Mapping[str, np.ndarray],\n) -> Dict[str, np.ndarray]:\n    """Estimate robust per-camera BGR gains from all valid overlap regions."""\n    camera_count = len(CAMERA_ORDER)\n    equations: List[np.ndarray] = []\n    channel_deltas: List[np.ndarray] = []\n\n    for left_index in range(camera_count):\n        left_camera = CAMERA_ORDER[left_index]\n        for right_index in range(left_index + 1, camera_count):\n            right_camera = CAMERA_ORDER[right_index]\n            overlap = (\n                (warped_masks[left_camera] > 0)\n                & (warped_masks[right_camera] > 0)\n            )\n            if int(np.count_nonzero(overlap)) < 500:\n                continue\n\n            left_pixels = warped_images[left_camera][overlap].astype(np.float32)\n            right_pixels = warped_images[right_camera][overlap].astype(np.float32)\n            deltas = []\n            usable_pair = True\n            for channel in range(3):\n                left_values = left_pixels[:, channel]\n                right_values = right_pixels[:, channel]\n                usable = (\n                    (left_values > 12.0)\n                    & (left_values < 243.0)\n                    & (right_values > 12.0)\n                    & (right_values < 243.0)\n                )\n                if int(np.count_nonzero(usable)) < 300:\n                    usable_pair = False\n                    break\n                # gain_left * left == gain_right * right\n                deltas.append(\n                    float(\n                        np.median(\n                            np.log(right_values[usable])\n                            - np.log(left_values[usable])\n                        )\n                    )\n                )\n            if not usable_pair:\n                continue\n\n            row = np.zeros(camera_count, dtype=np.float64)\n            row[left_index] = 1.0\n            row[right_index] = -1.0\n            equations.append(row)\n            channel_deltas.append(np.asarray(deltas, dtype=np.float64))\n\n    # Anchor the base camera to unit gain.  The other gains are estimated by a\n    # small least-squares graph, so the camera opposite the base can be reached\n    # through either adjacent camera.\n    anchor = np.zeros(camera_count, dtype=np.float64)\n    anchor[CAMERA_ORDER.index(BASE_CAMERA)] = 4.0\n    equations.append(anchor)\n    channel_deltas.append(np.zeros(3, dtype=np.float64))\n\n    matrix = np.stack(equations, axis=0)\n    targets = np.stack(channel_deltas, axis=0)\n    log_gains = np.linalg.lstsq(matrix, targets, rcond=None)[0]\n    gains = np.clip(np.exp(log_gains), 0.67, 1.5)\n\n    compensated = {}\n    for camera_index, camera in enumerate(CAMERA_ORDER):\n        corrected = (\n            warped_images[camera].astype(np.float32)\n            * gains[camera_index][None, None, :]\n        )\n        compensated[camera] = np.clip(corrected, 0, 255).astype(np.uint8)\n    return compensated\n\n\nclass NewUAVStitcher:\n    def __init__(\n        self,\n        calibrations: Mapping[str, CameraCalibration],\n        seam_feather_px: float,\n        exposure_compensation: bool,\n        refinement: Optional[Mapping[str, object]] = None,\n    ):\n        self.calibrations = calibrations\n        self.seam_feather_px = seam_feather_px\n        self.exposure_compensation = exposure_compensation\n        self.refinement = refinement\n        self.points_base = spherical_points()\n        self.luts = self._build_luts()\n\n    def _build_luts(self):\n        # Kalibr T_cam_imu maps IMU coordinates into camera coordinates.\n        # Therefore base-camera -> camera is:\n        #   T_cam_imu @ inverse(T_base_imu)\n        T_base_imu = self.calibrations[BASE_CAMERA].T_cam_imu\n        T_imu_base = np.linalg.inv(T_base_imu)\n\n        luts = {}\n        for camera in CAMERA_ORDER:\n            calibration = self.calibrations[camera]\n            if self.refinement is None:\n                T_base_to_cam = calibration.T_cam_imu @ T_imu_base\n            else:\n                camera_data = self.refinement["cameras"][camera]\n                rotation = np.asarray(\n                    camera_data["R_base_to_cam"], dtype=np.float64\n                )\n                center = np.asarray(\n                    camera_data["camera_center_in_base_m"], dtype=np.float64\n                )\n                T_base_to_cam = np.eye(4, dtype=np.float64)\n                T_base_to_cam[:3, :3] = rotation\n                T_base_to_cam[:3, 3] = -rotation @ center\n            luts[camera] = make_lut(\n                self.points_base, calibration, T_base_to_cam\n            )\n        return luts\n\n    def stitch(\n        self, files: Mapping[str, Path]\n    ) -> Tuple[np.ndarray, Dict[str, np.ndarray], Dict[str, np.ndarray]]:\n        warped_images: Dict[str, np.ndarray] = {}\n        warped_masks: Dict[str, np.ndarray] = {}\n\n        for camera in CAMERA_ORDER:\n            image = cv2.imread(str(files[camera]), cv2.IMREAD_COLOR)\n            if image is None:\n                raise RuntimeError(f"Cannot read image: {files[camera]}")\n\n            expected_width, expected_height = self.calibrations[camera].resolution\n            if image.shape[1::-1] != (expected_width, expected_height):\n                raise ValueError(\n                    f"{files[camera]} has {image.shape[1]}x{image.shape[0]}, "\n                    f"expected {expected_width}x{expected_height}"\n                )\n\n            # Do not flip the raw image.  The Kalibr intrinsics/extrinsics were\n            # estimated from the same raw camera orientation.\n            map_x, map_y, mask, _ = self.luts[camera]\n            warped = cv2.remap(\n                image,\n                map_x,\n                map_y,\n                cv2.INTER_LINEAR,\n                borderMode=cv2.BORDER_CONSTANT,\n                borderValue=(0, 0, 0),\n            )\n            warped_images[camera] = warped\n            warped_masks[camera] = mask\n\n        if self.exposure_compensation:\n            warped_images = compensate_exposure(warped_images, warped_masks)\n\n        panorama = seam_blend(\n            (warped_images[camera] for camera in CAMERA_ORDER),\n            (warped_masks[camera] for camera in CAMERA_ORDER),\n            (self.luts[camera][3] for camera in CAMERA_ORDER),\n            self.seam_feather_px,\n        )\n        # The new cameras were calibrated in their raw, physically inverted\n        # orientation.  Keep that orientation during projection so K, D and\n        # T_cam_imu remain valid, then orient only the completed panorama.\n        # Both axes must be flipped: the vertical flip makes the rig upright,\n        # while the horizontal flip makes left_front appear to the left of\n        # right_front in the final ERP.  Flipping raw cameras independently\n        # would invalidate the calibrated multi-camera geometry.\n        panorama = cv2.flip(panorama, -1)\n        return panorama, warped_images, warped_masks\n\n\ndef select_frames(\n    frames: List[SynchronizedFrame],\n    timestamp: Optional[float],\n    max_frames: Optional[int],\n    stride: int,\n) -> List[SynchronizedFrame]:\n    if timestamp is not None:\n        return [min(frames, key=lambda frame: abs(frame.timestamp - timestamp))]\n\n    selected = frames[::stride]\n    if max_frames is not None:\n        selected = selected[:max_frames]\n    return selected\n\n\ndef exclude_existing_panoramas(\n    frames: List[SynchronizedFrame],\n    panorama_dirs: Iterable[Path],\n    max_gap: float,\n) -> List[SynchronizedFrame]:\n    """Keep only synchronized frames without a timestamp-matched panorama."""\n    existing = []\n    for directory in panorama_dirs:\n        directory = directory.resolve()\n        if not directory.is_dir():\n            raise FileNotFoundError(f"Existing-panorama directory not found: {directory}")\n        for path in directory.iterdir():\n            if path.suffix.lower() not in {".jpg", ".jpeg", ".png"}:\n                continue\n            try:\n                existing.append(parse_timestamp(path))\n            except ValueError:\n                continue\n    if not existing:\n        return frames\n\n    # Deduplicate the same panorama timestamp across result directories, then\n    # solve timestamp association by smallest error first.  A chronological\n    # greedy match can associate a panorama with an earlier frame when two\n    # camera frames are only microseconds apart, leaving the exact frame out.\n    timestamps = sorted(set(existing))\n    frame_times = np.asarray([frame.timestamp for frame in frames])\n    candidate_pairs = []\n    for panorama_index, timestamp in enumerate(timestamps):\n        first = int(np.searchsorted(frame_times, timestamp - max_gap, side="left"))\n        last = int(np.searchsorted(frame_times, timestamp + max_gap, side="right"))\n        for frame_index in range(first, last):\n            candidate_pairs.append(\n                (abs(frame_times[frame_index] - timestamp), frame_index, panorama_index)\n            )\n    candidate_pairs.sort()\n    is_matched = [False] * len(frames)\n    used_panoramas = set()\n    for _, frame_index, panorama_index in candidate_pairs:\n        if not is_matched[frame_index] and panorama_index not in used_panoramas:\n            is_matched[frame_index] = True\n            used_panoramas.add(panorama_index)\n    return [frame for frame, matched in zip(frames, is_matched) if not matched]\n\n\ndef write_debug_images(\n    debug_dir: Path,\n    timestamp: float,\n    warped_images: Mapping[str, np.ndarray],\n    warped_masks: Mapping[str, np.ndarray],\n) -> None:\n    debug_dir.mkdir(parents=True, exist_ok=True)\n    frame_id = f"{timestamp:.6f}"\n    for camera in CAMERA_ORDER:\n        cv2.imwrite(\n            str(debug_dir / f"{frame_id}_{camera}_warped.jpg"),\n            warped_images[camera],\n        )\n        cv2.imwrite(\n            str(debug_dir / f"{frame_id}_{camera}_mask.png"),\n            warped_masks[camera],\n        )\n\n\ndef build_parser() -> argparse.ArgumentParser:\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("--input-dir", type=Path, default=DEFAULT_INPUT_DIR)\n    parser.add_argument(\n        "--cam-mapping",\n        type=Path,\n        help=(\n            "Optional text file containing \'topic -> logical_camera\' lines. "\n            "Use this when a recording has different ROS camera wiring."\n        ),\n    )\n    parser.add_argument("--calib-dir", type=Path, default=DEFAULT_CALIB_DIR)\n    parser.add_argument("--output-dir", type=Path, default=DEFAULT_OUTPUT_DIR)\n    parser.add_argument(\n        "--refinement-path", type=Path, default=DEFAULT_REFINEMENT_PATH\n    )\n    parser.add_argument(\n        "--estimate-refinement",\n        action="store_true",\n        help=(\n            "Estimate image-based relative rotations from synchronized flight "\n            "frames, save --refinement-path, and exit."\n        ),\n    )\n    parser.add_argument(\n        "--no-refinement",\n        action="store_true",\n        help="Ignore image-based refinement and use raw Kalibr extrinsics.",\n    )\n    parser.add_argument(\n        "--refinement-frames",\n        type=int,\n        default=8,\n        help="Number of evenly spaced flight frames used for refinement.",\n    )\n    parser.add_argument(\n        "--refinement-trim-seconds",\n        type=float,\n        default=40.0,\n        help="Exclude this many seconds at each end during refinement.",\n    )\n    parser.add_argument(\n        "--timestamp",\n        type=float,\n        help="Stitch only the synchronized frame nearest this timestamp.",\n    )\n    parser.add_argument(\n        "--max-sync-gap",\n        type=float,\n        default=0.02,\n        help="Maximum allowed inter-camera timestamp difference in seconds.",\n    )\n    parser.add_argument(\n        "--max-frames",\n        type=int,\n        help="Maximum number of frames to write (default: all).",\n    )\n    parser.add_argument("--stride", type=int, default=1)\n    parser.add_argument(\n        "--exclude-existing-dir",\n        action="append",\n        type=Path,\n        default=[],\n        help=(\n            "Exclude synchronized frames already represented by panoramas in "\n            "this directory. May be supplied more than once."\n        ),\n    )\n    parser.add_argument(\n        "--existing-max-gap",\n        type=float,\n        default=0.03,\n        help="Timestamp tolerance for --exclude-existing-dir (default: 0.03 s).",\n    )\n    parser.add_argument(\n        "--seam-feather-px",\n        type=float,\n        default=6.0,\n        help=(\n            "Gaussian seam transition width in panorama pixels. "\n            "Use 0 for a hard seam (default: 6)."\n        ),\n    )\n    parser.add_argument(\n        "--no-exposure-compensation",\n        action="store_true",\n        help="Disable robust per-camera color/exposure gain compensation.",\n    )\n    parser.add_argument(\n        "--debug",\n        action="store_true",\n        help="Save individual warped images and masks for selected frames.",\n    )\n    return parser\n\n\ndef main() -> None:\n    args = build_parser().parse_args()\n    if args.max_sync_gap < 0.0:\n        raise ValueError("--max-sync-gap must be non-negative")\n    if args.max_frames is not None and args.max_frames <= 0:\n        raise ValueError("--max-frames must be positive")\n    if args.stride <= 0:\n        raise ValueError("--stride must be positive")\n    if args.existing_max_gap < 0.0:\n        raise ValueError("--existing-max-gap must be non-negative")\n    if args.seam_feather_px < 0.0:\n        raise ValueError("--seam-feather-px must be non-negative")\n    if args.refinement_frames < 3:\n        raise ValueError("--refinement-frames must be at least 3")\n    if args.refinement_trim_seconds < 0.0:\n        raise ValueError("--refinement-trim-seconds must be non-negative")\n\n    calibrations = load_all_calibrations(args.calib_dir.resolve())\n    mapping_path = args.cam_mapping.resolve() if args.cam_mapping else None\n    topic_to_camera = load_topic_to_camera(mapping_path)\n    indices = build_image_indices(args.input_dir.resolve(), topic_to_camera)\n    synchronized = synchronize_frames(indices, args.max_sync_gap)\n    if not synchronized:\n        raise RuntimeError("No synchronized four-camera frames were found")\n\n    refinement_path = args.refinement_path.resolve()\n    if args.estimate_refinement:\n        estimate_image_alignment_refinement(\n            synchronized,\n            calibrations,\n            refinement_path,\n            args.refinement_frames,\n            args.refinement_trim_seconds,\n        )\n        return\n\n    refinement = None\n    if not args.no_refinement:\n        if not refinement_path.is_file():\n            raise FileNotFoundError(\n                f"Missing image alignment refinement: {refinement_path}. "\n                "Run once with --estimate-refinement or use --no-refinement."\n            )\n        with refinement_path.open("r", encoding="utf-8") as handle:\n            refinement = json.load(handle)\n\n    existing_dirs = list(args.exclude_existing_dir)\n    if args.output_dir.is_dir():\n        existing_dirs.append(args.output_dir)\n    candidates = exclude_existing_panoramas(\n        synchronized, existing_dirs, args.existing_max_gap\n    )\n    selected = select_frames(candidates, args.timestamp, args.max_frames, args.stride)\n    args.output_dir.mkdir(parents=True, exist_ok=True)\n    debug_dir = args.output_dir / "debug"\n\n    print(\n        f"Found {len(synchronized)} synchronized frames, "\n        f"{len(candidates)} without an existing panorama; "\n        f"processing {len(selected)} frame(s)."\n    )\n    stitcher = NewUAVStitcher(\n        calibrations,\n        args.seam_feather_px,\n        exposure_compensation=not args.no_exposure_compensation,\n        refinement=refinement,\n    )\n\n    for index, frame in enumerate(selected, start=1):\n        panorama, warped_images, warped_masks = stitcher.stitch(frame.files)\n        output_path = args.output_dir / f"pano_{frame.timestamp:.6f}.jpg"\n        if not cv2.imwrite(str(output_path), panorama):\n            raise RuntimeError(f"Failed to write {output_path}")\n        if args.debug:\n            write_debug_images(\n                debug_dir,\n                frame.timestamp,\n                warped_images,\n                warped_masks,\n            )\n        print(\n            f"[{index}/{len(selected)}] {output_path.name} "\n            f"(max sync gap {frame.max_sync_gap * 1000.0:.2f} ms)"\n        )\n\n\n', 'stitch_new_uav.py', "exec"), base_namespace, base_namespace)
