sys.modules["_adaptive"] = SimpleNamespace(**adaptive_namespace)
exec(compile('#!/usr/bin/env python3\n"""Experimental new-UAV stitcher with one adaptive global sphere radius.\n\nThe stable ``stitch_new_uav.py`` pipeline is left unchanged.  This script\nbuilds a small bank of projection LUTs, estimates which radius best aligns\nraw-image feature matches, smooths that estimate in inverse-depth space, and\nuses the nearest precomputed LUT for stitching.\n\nThis is intentionally a *global* depth model: it can adapt between a mostly\nnear and a mostly far scene, but it cannot align several very different scene\ndepths at the same seam.  The latter requires a local/depth-aware warp.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport json\nimport math\nimport sys\nimport time\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom typing import Dict, List, Mapping, Optional, Sequence, Tuple\n\nimport cv2\nimport numpy as np\n\n\nSCRIPT_DIR = Path(__file__).resolve().parent\nPROJECT_ROOT = SCRIPT_DIR.parent\nsys.path.insert(0, str(PROJECT_ROOT))\n\n\n\nDEFAULT_OUTPUT_DIR = (\n    PROJECT_ROOT / "output_panos/experiments/adaptive_radius_new_uav"\n)\nDEFAULT_COLOR_CALIBRATION_PATH = SCRIPT_DIR / "color_balance_calibration.json"\nDEFAULT_RADII_M = (3.0, 4.0, 5.0, 6.0, 8.0, 12.0, 20.0, 30.0)\n\n\n@dataclass\nclass RadiusEstimate:\n    raw_radius_m: float\n    accepted_radius_m: float\n    match_count: int\n    best_score_px: float\n    default_score_px: float\n    scores_px: Mapping[float, float]\n\n\ndef parse_radius_list(value: str) -> Tuple[float, ...]:\n    try:\n        radii = sorted({float(item.strip()) for item in value.split(",")})\n    except ValueError as exc:\n        raise argparse.ArgumentTypeError(\n            "radii must be comma-separated numbers"\n        ) from exc\n    if not radii or radii[0] <= 0.0:\n        raise argparse.ArgumentTypeError("all radii must be positive")\n    return tuple(radii)\n\n\ndef load_refinement(path: Path) -> Mapping[str, object]:\n    if not path.is_file():\n        raise FileNotFoundError(f"Missing image alignment refinement: {path}")\n    with path.open("r", encoding="utf-8") as handle:\n        return json.load(handle)\n\n\ndef load_static_chroma_gains(path: Path) -> np.ndarray:\n    if not path.is_file():\n        raise FileNotFoundError(f"Missing color balance calibration: {path}")\n    with path.open("r", encoding="utf-8") as handle:\n        cameras = json.load(handle)["cameras"]\n    gains = np.asarray(\n        [cameras[camera]["chroma_gain_bgr"] for camera in base.CAMERA_ORDER],\n        dtype=np.float64,\n    )\n    if gains.shape != (len(base.CAMERA_ORDER), 3) or np.any(gains <= 0.0):\n        raise ValueError(f"Invalid chroma gains in {path}")\n    # Chroma must not change brightness; normalize every camera to unit\n    # geometric mean before dynamic scalar exposure is applied.\n    gains /= np.exp(np.mean(np.log(gains), axis=1, keepdims=True))\n    return gains\n\n\ndef camera_geometry(\n    calibrations: Mapping[str, base.CameraCalibration],\n    refinement: Optional[Mapping[str, object]],\n) -> Dict[str, Tuple[np.ndarray, np.ndarray]]:\n    """Return base-to-camera rotations and camera centers in the base frame."""\n    geometry = {}\n    if refinement is not None:\n        for camera in base.CAMERA_ORDER:\n            camera_data = refinement["cameras"][camera]\n            geometry[camera] = (\n                np.asarray(camera_data["R_base_to_cam"], dtype=np.float64),\n                np.asarray(\n                    camera_data["camera_center_in_base_m"], dtype=np.float64\n                ),\n            )\n        return geometry\n\n    T_base_imu = calibrations[base.BASE_CAMERA].T_cam_imu\n    T_imu_base = np.linalg.inv(T_base_imu)\n    for camera in base.CAMERA_ORDER:\n        T_base_to_cam = calibrations[camera].T_cam_imu @ T_imu_base\n        rotation = T_base_to_cam[:3, :3]\n        center = -rotation.T @ T_base_to_cam[:3, 3]\n        geometry[camera] = (rotation, center)\n    return geometry\n\n\nclass LowResolutionFeatureMatcher:\n    """Match adjacent raw fisheye views once, before testing all radii."""\n\n    def __init__(\n        self,\n        calibrations: Mapping[str, base.CameraCalibration],\n        scale: float,\n        max_features: int,\n    ) -> None:\n        self.calibrations = calibrations\n        self.scale = scale\n        self.sift = cv2.SIFT_create(\n            nfeatures=max_features,\n            contrastThreshold=0.025,\n        )\n        self.matcher = cv2.BFMatcher(cv2.NORM_L2)\n\n    def _features(self, path: Path, camera: str):\n        image = cv2.imread(str(path), cv2.IMREAD_GRAYSCALE)\n        if image is None:\n            raise RuntimeError(f"Cannot read image: {path}")\n        if self.scale != 1.0:\n            image = cv2.resize(\n                image,\n                None,\n                fx=self.scale,\n                fy=self.scale,\n                interpolation=cv2.INTER_AREA,\n            )\n\n        calibration = self.calibrations[camera]\n        cx = calibration.K[0, 2] * self.scale\n        cy = calibration.K[1, 2] * self.scale\n        width, height = image.shape[1], image.shape[0]\n        radius = int(\n            min(cx, width - 1 - cx, cy, height - 1 - cy) * 0.97\n        )\n        mask = np.zeros_like(image)\n        cv2.circle(\n            mask,\n            (int(round(cx)), int(round(cy))),\n            radius,\n            255,\n            thickness=-1,\n        )\n        return self.sift.detectAndCompute(image, mask)\n\n    def match(\n        self, frame: base.SynchronizedFrame\n    ) -> Dict[Tuple[str, str], Tuple[np.ndarray, np.ndarray]]:\n        features = {\n            camera: self._features(frame.files[camera], camera)\n            for camera in base.CAMERA_ORDER\n        }\n        result = {}\n        for first_camera, second_camera in base.ADJACENT_CAMERA_PAIRS:\n            first_keypoints, first_descriptors = features[first_camera]\n            second_keypoints, second_descriptors = features[second_camera]\n            if first_descriptors is None or second_descriptors is None:\n                continue\n\n            forward = self.matcher.knnMatch(\n                first_descriptors, second_descriptors, k=2\n            )\n            reverse = self.matcher.knnMatch(\n                second_descriptors, first_descriptors, k=2\n            )\n            forward_good = {\n                pair[0].queryIdx: pair[0].trainIdx\n                for pair in forward\n                if len(pair) == 2 and pair[0].distance < 0.72 * pair[1].distance\n            }\n            reverse_good = {\n                pair[0].queryIdx: pair[0].trainIdx\n                for pair in reverse\n                if len(pair) == 2 and pair[0].distance < 0.72 * pair[1].distance\n            }\n            mutual = [\n                (first_index, second_index)\n                for first_index, second_index in forward_good.items()\n                if reverse_good.get(second_index) == first_index\n            ]\n            if len(mutual) < 8:\n                continue\n\n            first_points = np.asarray(\n                [first_keypoints[i].pt for i, _ in mutual], dtype=np.float64\n            ) / self.scale\n            second_points = np.asarray(\n                [second_keypoints[j].pt for _, j in mutual], dtype=np.float64\n            ) / self.scale\n            result[(first_camera, second_camera)] = (\n                base._unit_rays_from_keypoints(\n                    first_points, self.calibrations[first_camera]\n                ),\n                base._unit_rays_from_keypoints(\n                    second_points, self.calibrations[second_camera]\n                ),\n            )\n        return result\n\n\ndef rays_to_panorama(\n    rays_camera: np.ndarray,\n    rotation_base_to_camera: np.ndarray,\n    camera_center_base: np.ndarray,\n    radius_m: float,\n) -> Tuple[np.ndarray, np.ndarray]:\n    """Intersect raw-camera rays with a base-centered sphere."""\n    directions = (rotation_base_to_camera.T @ rays_camera.T).T\n    center_dot_direction = directions @ camera_center_base\n    discriminant = (\n        center_dot_direction**2\n        + radius_m**2\n        - float(camera_center_base @ camera_center_base)\n    )\n    valid = discriminant > 0.0\n    distance = -center_dot_direction + np.sqrt(np.maximum(discriminant, 0.0))\n    points = camera_center_base + distance[:, None] * directions\n    points /= np.linalg.norm(points, axis=1, keepdims=True)\n\n    theta = np.arctan2(points[:, 0], points[:, 2])\n    phi = np.arcsin(np.clip(points[:, 1], -1.0, 1.0))\n    vertical_fov = math.radians(base.VERTICAL_FOV_DEG)\n    x = (theta + math.pi) / (2.0 * math.pi) * base.PANO_WIDTH\n    y = (phi + vertical_fov / 2.0) / vertical_fov * (base.PANO_HEIGHT - 1)\n    valid &= (y >= 0.0) & (y < base.PANO_HEIGHT)\n    return np.column_stack((x, y)), valid\n\n\nclass AdaptiveRadiusEstimator:\n    def __init__(\n        self,\n        calibrations: Mapping[str, base.CameraCalibration],\n        refinement: Optional[Mapping[str, object]],\n        radii_m: Sequence[float],\n        default_radius_m: float,\n        feature_scale: float,\n        max_features: int,\n        min_matches: int,\n        min_improvement_px: float,\n    ) -> None:\n        self.radii_m = tuple(radii_m)\n        self.default_radius_m = default_radius_m\n        self.min_matches = min_matches\n        self.min_improvement_px = min_improvement_px\n        self.geometry = camera_geometry(calibrations, refinement)\n        self.matcher = LowResolutionFeatureMatcher(\n            calibrations, feature_scale, max_features\n        )\n\n    def _score_radius(\n        self,\n        matches: Mapping[Tuple[str, str], Tuple[np.ndarray, np.ndarray]],\n        radius_m: float,\n    ) -> float:\n        errors = []\n        for (first_camera, second_camera), (\n            first_rays,\n            second_rays,\n        ) in matches.items():\n            first_rotation, first_center = self.geometry[first_camera]\n            second_rotation, second_center = self.geometry[second_camera]\n            first_points, first_valid = rays_to_panorama(\n                first_rays, first_rotation, first_center, radius_m\n            )\n            second_points, second_valid = rays_to_panorama(\n                second_rays, second_rotation, second_center, radius_m\n            )\n            horizontal = np.abs(first_points[:, 0] - second_points[:, 0])\n            horizontal = np.minimum(horizontal, base.PANO_WIDTH - horizontal)\n            vertical = first_points[:, 1] - second_points[:, 1]\n            pair_errors = np.hypot(horizontal, vertical)\n            pair_errors = pair_errors[first_valid & second_valid]\n            errors.extend(pair_errors.tolist())\n        if not errors:\n            return float("inf")\n        # The median rejects isolated descriptor mismatches and lets the\n        # dominant scene depth drive this deliberately global model.\n        return float(np.median(np.asarray(errors)))\n\n    def estimate(self, frame: base.SynchronizedFrame) -> RadiusEstimate:\n        matches = self.matcher.match(frame)\n        match_count = sum(len(pair[0]) for pair in matches.values())\n        scores = {\n            radius: self._score_radius(matches, radius)\n            for radius in self.radii_m\n        }\n        raw_radius = min(scores, key=scores.get)\n        best_score = scores[raw_radius]\n        default_score = scores[self.default_radius_m]\n        improvement = default_score - best_score\n        reliable = (\n            match_count >= self.min_matches\n            and np.isfinite(best_score)\n            and improvement >= self.min_improvement_px\n        )\n        accepted_radius = raw_radius if reliable else self.default_radius_m\n        return RadiusEstimate(\n            raw_radius_m=raw_radius,\n            accepted_radius_m=accepted_radius,\n            match_count=match_count,\n            best_score_px=best_score,\n            default_score_px=default_score,\n            scores_px=scores,\n        )\n\n\ndef build_normalized_seam_weights(luts, feather_px: float) -> np.ndarray:\n    masks = [luts[camera][2] for camera in base.CAMERA_ORDER]\n    confidence_stack = np.stack(\n        [luts[camera][3] for camera in base.CAMERA_ORDER], axis=0\n    )\n    valid_stack = np.stack([mask > 0 for mask in masks], axis=0)\n    confidence_stack = np.where(valid_stack, confidence_stack, -np.inf)\n    coverage = np.any(valid_stack, axis=0)\n    winner = np.argmax(confidence_stack, axis=0)\n    weights = []\n    for camera_index, mask in enumerate(masks):\n        hard = ((winner == camera_index) & coverage).astype(np.float32)\n        weight = base._horizontal_wrap_blur(hard, feather_px)\n        weights.append(weight * (mask > 0).astype(np.float32))\n    weights = np.stack(weights, axis=0)\n    total = np.sum(weights, axis=0, keepdims=True)\n    return np.divide(\n        weights,\n        total,\n        out=np.zeros_like(weights),\n        where=total > 1e-6,\n    )\n\n\ndef weighted_blend(\n    images: Mapping[str, np.ndarray], weights: np.ndarray\n) -> np.ndarray:\n    canvas = np.zeros(\n        (base.PANO_HEIGHT, base.PANO_WIDTH, 3), dtype=np.float32\n    )\n    for index, camera in enumerate(base.CAMERA_ORDER):\n        canvas += images[camera].astype(np.float32) * weights[index][..., None]\n    return canvas\n\n\ndef normalized_lowpass(\n    image: np.ndarray, mask: np.ndarray, sigma: float\n) -> np.ndarray:\n    valid = (mask > 0).astype(np.float32)\n    numerator = base._horizontal_wrap_blur(\n        image.astype(np.float32) * valid[..., None], sigma\n    )\n    denominator = base._horizontal_wrap_blur(valid, sigma)\n    return np.divide(\n        numerator,\n        denominator[..., None],\n        out=np.zeros_like(numerator),\n        where=denominator[..., None] > 1e-5,\n    )\n\n\nclass RadiusLUTBank:\n    """Build each projection once; runtime radius changes do not rebuild LUTs."""\n\n    def __init__(\n        self,\n        calibrations: Mapping[str, base.CameraCalibration],\n        refinement: Optional[Mapping[str, object]],\n        radii_m: Sequence[float],\n        seam_feather_px: float,\n        low_frequency_sigma_px: float,\n        low_frequency_seam_feather_px: float,\n        exposure_compensation: bool,\n    ) -> None:\n        self.calibrations = calibrations\n        self.exposure_compensation = exposure_compensation\n        self.low_frequency_sigma_px = low_frequency_sigma_px\n        original_radius = base.SPHERE_RADIUS_M\n        self.stitchers = {}\n        self.seam_weights = {}\n        try:\n            for radius in radii_m:\n                base.SPHERE_RADIUS_M = float(radius)\n                self.stitchers[float(radius)] = base.NewUAVStitcher(\n                    calibrations,\n                    seam_feather_px,\n                    # Exposure is handled separately using gains estimated\n                    # at the stable reference radius.  Letting every radius\n                    # estimate its own gains makes parallax look like a large\n                    # per-channel exposure change and creates colored panels.\n                    False,\n                    refinement,\n                )\n                luts = self.stitchers[float(radius)].luts\n                self.seam_weights[float(radius)] = (\n                    build_normalized_seam_weights(luts, seam_feather_px),\n                    build_normalized_seam_weights(\n                        luts, low_frequency_seam_feather_px\n                    ),\n                )\n        finally:\n            base.SPHERE_RADIUS_M = original_radius\n\n    def nearest_radius(self, radius_m: float) -> float:\n        # Projection translation varies approximately linearly with inverse\n        # depth, so choose the nearest bank entry in inverse-depth space.\n        return min(\n            self.stitchers,\n            key=lambda candidate: abs(1.0 / candidate - 1.0 / radius_m),\n        )\n\n    def read_images(self, files) -> Dict[str, np.ndarray]:\n        images = {}\n        for camera in base.CAMERA_ORDER:\n            image = cv2.imread(str(files[camera]), cv2.IMREAD_COLOR)\n            if image is None:\n                raise RuntimeError(f"Cannot read image: {files[camera]}")\n            expected = self.calibrations[camera].resolution\n            if image.shape[1::-1] != expected:\n                raise ValueError(\n                    f"{files[camera]} has {image.shape[1]}x{image.shape[0]}, "\n                    f"expected {expected[0]}x{expected[1]}"\n                )\n            images[camera] = image\n        return images\n\n    def warp(\n        self, radius_m: float, raw_images: Mapping[str, np.ndarray]\n    ) -> Tuple[float, Dict[str, np.ndarray], Dict[str, np.ndarray]]:\n        selected = self.nearest_radius(radius_m)\n        stitcher = self.stitchers[selected]\n        warped_images = {}\n        warped_masks = {}\n        for camera in base.CAMERA_ORDER:\n            map_x, map_y, mask, _ = stitcher.luts[camera]\n            warped_images[camera] = cv2.remap(\n                raw_images[camera],\n                map_x,\n                map_y,\n                cv2.INTER_LINEAR,\n                borderMode=cv2.BORDER_CONSTANT,\n                borderValue=(0, 0, 0),\n            )\n            warped_masks[camera] = mask\n        return selected, warped_images, warped_masks\n\n    def blend(\n        self,\n        selected_radius_m: float,\n        warped_images: Mapping[str, np.ndarray],\n        warped_masks: Mapping[str, np.ndarray],\n        gains: Optional[np.ndarray],\n    ) -> Tuple[np.ndarray, Dict[str, np.ndarray]]:\n        corrected = dict(warped_images)\n        if self.exposure_compensation and gains is not None:\n            corrected = apply_exposure_gains(corrected, gains)\n        narrow_weights, wide_weights = self.seam_weights[selected_radius_m]\n        if self.low_frequency_sigma_px > 0.0:\n            low_images = {\n                camera: normalized_lowpass(\n                    corrected[camera],\n                    warped_masks[camera],\n                    self.low_frequency_sigma_px,\n                )\n                for camera in base.CAMERA_ORDER\n            }\n            high_images = {\n                camera: corrected[camera].astype(np.float32)\n                - low_images[camera]\n                for camera in base.CAMERA_ORDER\n            }\n            panorama = weighted_blend(low_images, wide_weights)\n            panorama += weighted_blend(high_images, narrow_weights)\n        else:\n            panorama = weighted_blend(corrected, narrow_weights)\n        panorama = np.clip(panorama, 0.0, 255.0).astype(np.uint8)\n        # Match the final ERP orientation used by stitch_new_uav.py: upright\n        # and with physical left/right preserved in the displayed panorama.\n        return cv2.flip(panorama, -1), corrected\n\n\ndef estimate_exposure_gains(\n    warped_images: Mapping[str, np.ndarray],\n    warped_masks: Mapping[str, np.ndarray],\n) -> np.ndarray:\n    """Use the stable reference projection to estimate per-camera BGR gains."""\n    camera_count = len(base.CAMERA_ORDER)\n    equations = []\n    channel_deltas = []\n    for first_index in range(camera_count):\n        first_camera = base.CAMERA_ORDER[first_index]\n        for second_index in range(first_index + 1, camera_count):\n            second_camera = base.CAMERA_ORDER[second_index]\n            overlap = (\n                (warped_masks[first_camera] > 0)\n                & (warped_masks[second_camera] > 0)\n            )\n            if int(np.count_nonzero(overlap)) < 500:\n                continue\n            first = warped_images[first_camera][overlap].astype(np.float32)\n            second = warped_images[second_camera][overlap].astype(np.float32)\n            deltas = []\n            for channel in range(3):\n                first_values = first[:, channel]\n                second_values = second[:, channel]\n                usable = (\n                    (first_values > 12.0)\n                    & (first_values < 243.0)\n                    & (second_values > 12.0)\n                    & (second_values < 243.0)\n                )\n                if int(np.count_nonzero(usable)) < 300:\n                    break\n                deltas.append(\n                    float(\n                        np.median(\n                            np.log(second_values[usable])\n                            - np.log(first_values[usable])\n                        )\n                    )\n                )\n            if len(deltas) != 3:\n                continue\n            row = np.zeros(camera_count, dtype=np.float64)\n            row[first_index] = 1.0\n            row[second_index] = -1.0\n            equations.append(row)\n            channel_deltas.append(deltas)\n\n    anchor = np.zeros(camera_count, dtype=np.float64)\n    anchor[base.CAMERA_ORDER.index(base.BASE_CAMERA)] = 4.0\n    equations.append(anchor)\n    channel_deltas.append([0.0, 0.0, 0.0])\n    log_gains = np.linalg.lstsq(\n        np.asarray(equations), np.asarray(channel_deltas), rcond=None\n    )[0]\n    return np.clip(np.exp(log_gains), 0.67, 1.5)\n\n\ndef constrain_gains_to_static_chroma(\n    observed_gains: np.ndarray, static_chroma_gains: np.ndarray\n) -> np.ndarray:\n    """Keep dynamic exposure scalar while preventing per-frame WB shifts."""\n    exposure = np.exp(np.mean(np.log(observed_gains), axis=1, keepdims=True))\n    return np.clip(exposure * static_chroma_gains, 0.67, 1.5)\n\n\ndef apply_exposure_gains(\n    images: Mapping[str, np.ndarray], gains: np.ndarray\n) -> Dict[str, np.ndarray]:\n    return {\n        camera: np.clip(\n            images[camera].astype(np.float32)\n            * gains[index][None, None, :],\n            0.0,\n            255.0,\n        ).astype(np.uint8)\n        for index, camera in enumerate(base.CAMERA_ORDER)\n    }\n\n\ndef build_parser() -> argparse.ArgumentParser:\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("--input-dir", type=Path, default=base.DEFAULT_INPUT_DIR)\n    parser.add_argument("--calib-dir", type=Path, default=base.DEFAULT_CALIB_DIR)\n    parser.add_argument(\n        "--refinement-path", type=Path, default=base.DEFAULT_REFINEMENT_PATH\n    )\n    parser.add_argument(\n        "--color-calibration-path",\n        type=Path,\n        default=DEFAULT_COLOR_CALIBRATION_PATH,\n    )\n    parser.add_argument("--no-refinement", action="store_true")\n    parser.add_argument("--output-dir", type=Path, default=DEFAULT_OUTPUT_DIR)\n    parser.add_argument("--timestamp", type=float)\n    parser.add_argument("--max-frames", type=int)\n    parser.add_argument("--stride", type=int, default=1)\n    parser.add_argument("--max-sync-gap", type=float, default=0.02)\n    parser.add_argument(\n        "--radii",\n        type=parse_radius_list,\n        default=DEFAULT_RADII_M,\n        help="Precomputed radii in metres (default: 3,4,5,6,8,12,20,30).",\n    )\n    parser.add_argument("--default-radius", type=float, default=30.0)\n    parser.add_argument("--radius-update-interval", type=int, default=10)\n    parser.add_argument(\n        "--smoothing-alpha",\n        type=float,\n        default=0.35,\n        help="Inverse-depth EMA coefficient; 1 disables smoothing.",\n    )\n    parser.add_argument("--feature-scale", type=float, default=0.5)\n    parser.add_argument("--max-features", type=int, default=2000)\n    parser.add_argument("--min-matches", type=int, default=30)\n    parser.add_argument("--min-improvement-px", type=float, default=0.25)\n    parser.add_argument("--seam-feather-px", type=float, default=6.0)\n    parser.add_argument("--low-frequency-sigma-px", type=float, default=12.0)\n    parser.add_argument(\n        "--low-frequency-seam-feather-px", type=float, default=36.0\n    )\n    parser.add_argument("--no-exposure-compensation", action="store_true")\n    parser.add_argument(\n        "--exposure-update-interval",\n        type=int,\n        default=10,\n        help="Estimate reference-radius color gains every N frames.",\n    )\n    parser.add_argument(\n        "--exposure-smoothing-alpha",\n        type=float,\n        default=0.25,\n        help="Log-gain EMA coefficient; 1 disables gain smoothing.",\n    )\n    parser.add_argument(\n        "--write-fixed-comparison",\n        action="store_true",\n        help="Also write the same frames with the default-radius LUT.",\n    )\n    parser.add_argument("--debug", action="store_true")\n    return parser\n\n\ndef validate_args(args) -> None:\n    if args.default_radius not in args.radii:\n        raise ValueError("--default-radius must be one of --radii")\n    if args.radius_update_interval <= 0:\n        raise ValueError("--radius-update-interval must be positive")\n    if not 0.0 < args.smoothing_alpha <= 1.0:\n        raise ValueError("--smoothing-alpha must be in (0, 1]")\n    if not 0.0 < args.feature_scale <= 1.0:\n        raise ValueError("--feature-scale must be in (0, 1]")\n    if args.max_features < 100:\n        raise ValueError("--max-features must be at least 100")\n    if args.min_matches < 1:\n        raise ValueError("--min-matches must be positive")\n    if args.min_improvement_px < 0.0:\n        raise ValueError("--min-improvement-px must be non-negative")\n    if args.seam_feather_px < 0.0:\n        raise ValueError("--seam-feather-px must be non-negative")\n    if args.low_frequency_sigma_px < 0.0:\n        raise ValueError("--low-frequency-sigma-px must be non-negative")\n    if args.low_frequency_seam_feather_px < args.seam_feather_px:\n        raise ValueError(\n            "--low-frequency-seam-feather-px must be at least "\n            "--seam-feather-px"\n        )\n    if args.exposure_update_interval <= 0:\n        raise ValueError("--exposure-update-interval must be positive")\n    if not 0.0 < args.exposure_smoothing_alpha <= 1.0:\n        raise ValueError("--exposure-smoothing-alpha must be in (0, 1]")\n    if args.max_frames is not None and args.max_frames <= 0:\n        raise ValueError("--max-frames must be positive")\n    if args.stride <= 0:\n        raise ValueError("--stride must be positive")\n\n\ndef main() -> None:\n    args = build_parser().parse_args()\n    validate_args(args)\n\n    calibrations = base.load_all_calibrations(args.calib_dir.resolve())\n    refinement = None\n    if not args.no_refinement:\n        refinement = load_refinement(args.refinement_path.resolve())\n    static_chroma_gains = load_static_chroma_gains(\n        args.color_calibration_path.resolve()\n    )\n\n    indices = base.build_image_indices(args.input_dir.resolve())\n    frames = base.synchronize_frames(indices, args.max_sync_gap)\n    selected = base.select_frames(\n        frames, args.timestamp, args.max_frames, args.stride\n    )\n    if not selected:\n        raise RuntimeError("No synchronized frames selected")\n\n    adaptive_dir = args.output_dir.resolve() / "adaptive"\n    fixed_dir = (\n        args.output_dir.resolve() / f"fixed_{args.default_radius:g}m"\n    )\n    adaptive_dir.mkdir(parents=True, exist_ok=True)\n    if args.write_fixed_comparison:\n        fixed_dir.mkdir(parents=True, exist_ok=True)\n\n    print(f"Building {len(args.radii)} projection LUT banks: {args.radii}")\n    bank = RadiusLUTBank(\n        calibrations,\n        refinement,\n        args.radii,\n        args.seam_feather_px,\n        args.low_frequency_sigma_px,\n        args.low_frequency_seam_feather_px,\n        exposure_compensation=not args.no_exposure_compensation,\n    )\n    estimator = AdaptiveRadiusEstimator(\n        calibrations,\n        refinement,\n        args.radii,\n        args.default_radius,\n        args.feature_scale,\n        args.max_features,\n        args.min_matches,\n        args.min_improvement_px,\n    )\n\n    report_rows: List[Dict[str, object]] = []\n    smoothed_inverse_depth = None\n    current_radius = args.default_radius\n    last_estimate: Optional[RadiusEstimate] = None\n    smoothed_log_gains: Optional[np.ndarray] = None\n\n    for index, frame in enumerate(selected):\n        estimate_ms = 0.0\n        updated = index % args.radius_update_interval == 0\n        if updated:\n            start = time.perf_counter()\n            last_estimate = estimator.estimate(frame)\n            estimate_ms = (time.perf_counter() - start) * 1000.0\n            observed_inverse = 1.0 / last_estimate.accepted_radius_m\n            if smoothed_inverse_depth is None:\n                smoothed_inverse_depth = observed_inverse\n            else:\n                alpha = args.smoothing_alpha\n                smoothed_inverse_depth = (\n                    (1.0 - alpha) * smoothed_inverse_depth\n                    + alpha * observed_inverse\n                )\n            current_radius = 1.0 / smoothed_inverse_depth\n\n        raw_images = bank.read_images(frame.files)\n        exposure_ms = 0.0\n        exposure_updated = (\n            not args.no_exposure_compensation\n            and (\n                smoothed_log_gains is None\n                or index % args.exposure_update_interval == 0\n            )\n        )\n        reference_warp = None\n        if exposure_updated:\n            start = time.perf_counter()\n            reference_warp = bank.warp(args.default_radius, raw_images)\n            _, reference_images, reference_masks = reference_warp\n            observed_gains = estimate_exposure_gains(\n                reference_images, reference_masks\n            )\n            observed_gains = constrain_gains_to_static_chroma(\n                observed_gains, static_chroma_gains\n            )\n            observed_log_gains = np.log(observed_gains)\n            if smoothed_log_gains is None:\n                smoothed_log_gains = observed_log_gains\n            else:\n                alpha = args.exposure_smoothing_alpha\n                smoothed_log_gains = (\n                    (1.0 - alpha) * smoothed_log_gains\n                    + alpha * observed_log_gains\n                )\n            exposure_ms = (time.perf_counter() - start) * 1000.0\n        gains = (\n            np.exp(smoothed_log_gains)\n            if smoothed_log_gains is not None\n            else None\n        )\n\n        start = time.perf_counter()\n        used_radius, warped_images, warped_masks = bank.warp(\n            current_radius, raw_images\n        )\n        panorama, warped_images = bank.blend(\n            used_radius, warped_images, warped_masks, gains\n        )\n        stitch_ms = (time.perf_counter() - start) * 1000.0\n        output_path = adaptive_dir / f"pano_{frame.timestamp:.6f}.jpg"\n        if not cv2.imwrite(str(output_path), panorama):\n            raise RuntimeError(f"Failed to write {output_path}")\n\n        if args.write_fixed_comparison:\n            if reference_warp is None:\n                reference_warp = bank.warp(args.default_radius, raw_images)\n            fixed_radius, fixed_images, fixed_masks = reference_warp\n            fixed_panorama, _ = bank.blend(\n                fixed_radius, fixed_images, fixed_masks, gains\n            )\n            fixed_path = fixed_dir / f"pano_{frame.timestamp:.6f}.jpg"\n            if not cv2.imwrite(str(fixed_path), fixed_panorama):\n                raise RuntimeError(f"Failed to write {fixed_path}")\n\n        if args.debug:\n            base.write_debug_images(\n                args.output_dir.resolve() / "debug",\n                frame.timestamp,\n                warped_images,\n                warped_masks,\n            )\n\n        estimate = last_estimate\n        accepted_score = ""\n        improvement = ""\n        if updated and estimate is not None:\n            if estimate.accepted_radius_m == estimate.raw_radius_m:\n                accepted_score_value = estimate.best_score_px\n            else:\n                accepted_score_value = estimate.default_score_px\n            accepted_score = f"{accepted_score_value:.3f}"\n            improvement = (\n                f"{estimate.default_score_px - accepted_score_value:.3f}"\n            )\n        report_rows.append(\n            {\n                "timestamp": f"{frame.timestamp:.6f}",\n                "updated": int(updated),\n                "raw_radius_m": (\n                    f"{estimate.raw_radius_m:.3f}" if updated and estimate else ""\n                ),\n                "accepted_radius_m": (\n                    f"{estimate.accepted_radius_m:.3f}"\n                    if updated and estimate\n                    else ""\n                ),\n                "smoothed_radius_m": f"{current_radius:.3f}",\n                "used_lut_radius_m": f"{used_radius:.3f}",\n                "match_count": estimate.match_count if updated and estimate else "",\n                "best_score_px": (\n                    f"{estimate.best_score_px:.3f}"\n                    if updated and estimate\n                    else ""\n                ),\n                "default_score_px": (\n                    f"{estimate.default_score_px:.3f}"\n                    if updated and estimate\n                    else ""\n                ),\n                "accepted_score_px": accepted_score,\n                "score_improvement_px": improvement,\n                "estimate_ms": f"{estimate_ms:.2f}",\n                "exposure_updated": int(exposure_updated),\n                "exposure_ms": f"{exposure_ms:.2f}",\n                "exposure_gains_bgr": (\n                    json.dumps(np.round(gains, 5).tolist())\n                    if gains is not None\n                    else ""\n                ),\n                "stitch_ms": f"{stitch_ms:.2f}",\n                "max_sync_gap_ms": f"{frame.max_sync_gap * 1000.0:.3f}",\n            }\n        )\n        estimate_text = "reuse"\n        if updated and estimate is not None:\n            estimate_text = (\n                f"raw={estimate.raw_radius_m:g}m, "\n                f"accepted={estimate.accepted_radius_m:g}m, "\n                f"matches={estimate.match_count}, "\n                f"score={estimate.best_score_px:.2f}/"\n                f"{estimate.default_score_px:.2f}px"\n            )\n        print(\n            f"[{index + 1}/{len(selected)}] {output_path.name}: "\n            f"{estimate_text}; smooth={current_radius:.1f}m, "\n            f"LUT={used_radius:g}m, estimate={estimate_ms:.1f}ms, "\n            f"exposure={exposure_ms:.1f}ms, stitch={stitch_ms:.1f}ms"\n        )\n\n    report_path = args.output_dir.resolve() / "adaptive_radius_report.csv"\n    with report_path.open("w", newline="", encoding="utf-8") as handle:\n        writer = csv.DictWriter(handle, fieldnames=list(report_rows[0]))\n        writer.writeheader()\n        writer.writerows(report_rows)\n    print(f"Saved report: {report_path}")\n\n\n', 'stitch_new_uav_adaptive_radius.py', "exec"), adaptive_namespace, adaptive_namespace)
