exec(compile('#!/usr/bin/env python3\n"""Depth-layered, per-seam panorama stitching for the new UAV.\n\nThe stable stitcher remains unchanged.  This experimental pipeline estimates\none of five indoor-to-outdoor projection depths independently for each adjacent camera overlap,\nuses temporal hysteresis to avoid radius flicker, replaces geometry only near\nthe affected seam, and finds a low-cost seam through the locally warped views.\n\nIt is deliberately lighter than dense depth-aware warping: only a small LUT\nbank, feature matching in the four overlaps, and dynamic-programming seams are\nneeded.  The method can handle different dominant depths around the panorama;\nseveral depths crossing the exact same object still require dense disparity.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport json\nimport math\nimport sys\nimport time\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom typing import Dict, List, Mapping, Optional, Sequence, Tuple\n\nimport cv2\nimport numpy as np\n\n\nSCRIPT_DIR = Path(__file__).resolve().parent\nPROJECT_ROOT = SCRIPT_DIR.parent\nsys.path.insert(0, str(PROJECT_ROOT))\n\n\n\nDEFAULT_OUTPUT_DIR = (\n    PROJECT_ROOT / "output_panos/experiments/multiseam_radius_new_uav"\n)\nDEFAULT_LAYERS_M = (1.0, 2.0, 4.0, 12.0, 30.0)\nPair = Tuple[str, str]\n\n\n@dataclass\nclass PairEstimate:\n    match_count: int\n    raw_radius_m: float\n    scores_px: Mapping[float, float]\n\n\n@dataclass\nclass PairState:\n    radius_m: float\n    pending_radius_m: Optional[float] = None\n    pending_count: int = 0\n\n\n@dataclass(frozen=True)\nclass SeamGeometry:\n    center_x: int\n    left_camera: str\n    right_camera: str\n\n\ndef parse_float_list(value: str) -> Tuple[float, ...]:\n    try:\n        values = tuple(sorted({float(item.strip()) for item in value.split(",")}))\n    except ValueError as exc:\n        raise argparse.ArgumentTypeError("expected comma-separated numbers") from exc\n    if not values or values[0] <= 0.0:\n        raise argparse.ArgumentTypeError("all values must be positive")\n    return values\n\n\ndef parse_timestamps(value: str) -> Tuple[float, ...]:\n    try:\n        return tuple(float(item.strip()) for item in value.split(",") if item.strip())\n    except ValueError as exc:\n        raise argparse.ArgumentTypeError("timestamps must be comma-separated") from exc\n\n\nclass PerSeamRadiusEstimator:\n    def __init__(\n        self,\n        calibrations: Mapping[str, base.CameraCalibration],\n        refinement: Optional[Mapping[str, object]],\n        layers_m: Sequence[float],\n        feature_scale: float,\n        max_features: int,\n        score_quantile: float,\n        match_geometry_max_error_px: float,\n    ) -> None:\n        self.layers_m = tuple(float(value) for value in layers_m)\n        self.geometry = adaptive.camera_geometry(calibrations, refinement)\n        self.matcher = adaptive.LowResolutionFeatureMatcher(\n            calibrations, feature_scale, max_features\n        )\n        self.score_quantile = score_quantile\n        self.match_geometry_max_error_px = match_geometry_max_error_px\n\n    def _pair_errors(\n        self,\n        pair: Pair,\n        rays: Tuple[np.ndarray, np.ndarray],\n        radius_m: float,\n    ) -> np.ndarray:\n        first_camera, second_camera = pair\n        first_rotation, first_center = self.geometry[first_camera]\n        second_rotation, second_center = self.geometry[second_camera]\n        first_points, first_valid = adaptive.rays_to_panorama(\n            rays[0], first_rotation, first_center, radius_m\n        )\n        second_points, second_valid = adaptive.rays_to_panorama(\n            rays[1], second_rotation, second_center, radius_m\n        )\n        horizontal = np.abs(first_points[:, 0] - second_points[:, 0])\n        horizontal = np.minimum(horizontal, base.PANO_WIDTH - horizontal)\n        vertical = first_points[:, 1] - second_points[:, 1]\n        errors = np.full(len(horizontal), np.inf, dtype=np.float64)\n        valid = first_valid & second_valid\n        errors[valid] = np.hypot(horizontal[valid], vertical[valid])\n        return errors\n\n    def estimate(self, frame: base.SynchronizedFrame) -> Dict[Pair, PairEstimate]:\n        matches = self.matcher.match(frame)\n        estimates = {}\n        for pair in base.ADJACENT_CAMERA_PAIRS:\n            rays = matches.get(pair)\n            if rays is None:\n                estimates[pair] = PairEstimate(\n                    match_count=0,\n                    raw_radius_m=max(self.layers_m),\n                    scores_px={radius: float("inf") for radius in self.layers_m},\n                )\n                continue\n            errors_by_radius = {\n                radius: self._pair_errors(pair, rays, radius)\n                for radius in self.layers_m\n            }\n            # Repeated indoor textures (checkerboards, ceiling lights) can pass\n            # descriptor ratio and mutual checks while being geometrically\n            # impossible. Keep a correspondence only if at least one candidate\n            # depth explains it within a deliberately loose panorama threshold.\n            minimum_error = np.min(\n                np.stack(list(errors_by_radius.values()), axis=0), axis=0\n            )\n            geometric_inliers = (\n                np.isfinite(minimum_error)\n                & (minimum_error <= self.match_geometry_max_error_px)\n            )\n            scores = {}\n            for radius, errors in errors_by_radius.items():\n                usable = errors[geometric_inliers & np.isfinite(errors)]\n                scores[radius] = (\n                    float(np.quantile(usable, self.score_quantile))\n                    if len(usable)\n                    else float("inf")\n                )\n            best = min(scores, key=scores.get)\n            estimates[pair] = PairEstimate(\n                int(np.count_nonzero(geometric_inliers)), best, scores\n            )\n        return estimates\n\n\nclass RadiusHysteresis:\n    def __init__(\n        self,\n        pairs: Sequence[Pair],\n        default_radius_m: float,\n        min_matches: int,\n        switch_margin_px: float,\n        confirmations: int,\n        fast_switch_margin_px: Optional[float] = None,\n    ) -> None:\n        self.states = {pair: PairState(default_radius_m) for pair in pairs}\n        self.min_matches = min_matches\n        self.switch_margin_px = switch_margin_px\n        self.confirmations = confirmations\n        self.fast_switch_margin_px = fast_switch_margin_px\n\n    def update(\n        self,\n        estimates: Mapping[Pair, PairEstimate],\n        photometric_fallbacks: Optional[\n            Mapping[Pair, Tuple[float, Mapping[float, float]]]\n        ] = None,\n        photometric_switch_margin: float = 0.0,\n    ) -> Dict[Pair, float]:\n        for pair, estimate in estimates.items():\n            state = self.states[pair]\n            required_confirmations = self.confirmations\n            feature_reliable = (\n                estimate.match_count >= self.min_matches\n            )\n            if feature_reliable:\n                candidate = estimate.raw_radius_m\n                current_score = estimate.scores_px.get(\n                    state.radius_m, float("inf")\n                )\n                candidate_score = estimate.scores_px.get(candidate, float("inf"))\n                reliable = (\n                    np.isfinite(candidate_score)\n                    and current_score - candidate_score >= self.switch_margin_px\n                )\n                if (\n                    reliable\n                    and self.fast_switch_margin_px is not None\n                    and current_score - candidate_score\n                    >= self.fast_switch_margin_px\n                ):\n                    required_confirmations = 1\n            elif photometric_fallbacks and pair in photometric_fallbacks:\n                candidate, scores = photometric_fallbacks[pair]\n                current_score = scores.get(state.radius_m, float("inf"))\n                candidate_score = scores.get(candidate, float("inf"))\n                reliable = (\n                    np.isfinite(candidate_score)\n                    and current_score - candidate_score\n                    >= photometric_switch_margin\n                )\n            else:\n                candidate = state.radius_m\n                reliable = False\n            if candidate == state.radius_m or not reliable:\n                state.pending_radius_m = None\n                state.pending_count = 0\n                continue\n            if state.pending_radius_m == candidate:\n                state.pending_count += 1\n            else:\n                state.pending_radius_m = candidate\n                state.pending_count = 1\n            if state.pending_count >= required_confirmations:\n                state.radius_m = candidate\n                state.pending_radius_m = None\n                state.pending_count = 0\n        return {pair: state.radius_m for pair, state in self.states.items()}\n\n\ndef reference_winner(luts) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:\n    confidence = np.stack(\n        [luts[camera][3] for camera in base.CAMERA_ORDER], axis=0\n    )\n    valid = np.stack(\n        [luts[camera][2] > 0 for camera in base.CAMERA_ORDER], axis=0\n    )\n    confidence = np.where(valid, confidence, -np.inf)\n    coverage = np.any(valid, axis=0)\n    return np.argmax(confidence, axis=0), coverage, confidence\n\n\ndef circular_distance(first: np.ndarray, second: float, period: int) -> np.ndarray:\n    distance = np.abs(first - second)\n    return np.minimum(distance, period - distance)\n\n\ndef find_seam_geometry(luts) -> Tuple[Dict[Pair, SeamGeometry], np.ndarray, np.ndarray]:\n    winner, coverage, confidence = reference_winner(luts)\n    width = winner.shape[1]\n    geometry = {}\n    for pair in base.ADJACENT_CAMERA_PAIRS:\n        first_index = base.CAMERA_ORDER.index(pair[0])\n        second_index = base.CAMERA_ORDER.index(pair[1])\n        histogram = np.zeros(width, dtype=np.float64)\n        for x in range(width):\n            right = (x + 1) % width\n            transition = (\n                ((winner[:, x] == first_index) & (winner[:, right] == second_index))\n                | ((winner[:, x] == second_index) & (winner[:, right] == first_index))\n            ) & coverage[:, x] & coverage[:, right]\n            histogram[x] = float(np.count_nonzero(transition))\n        if not np.any(histogram):\n            both = np.isfinite(confidence[first_index]) & np.isfinite(\n                confidence[second_index]\n            )\n            difference = np.where(\n                both,\n                np.abs(confidence[first_index] - confidence[second_index]),\n                np.inf,\n            )\n            column_score = np.min(difference, axis=0)\n            center = int(np.argmin(column_score))\n        else:\n            extended = np.r_[histogram, histogram, histogram]\n            smoothed = cv2.GaussianBlur(\n                extended[None, :], (0, 0), sigmaX=5.0\n            )[0, width : 2 * width]\n            center = int(np.argmax(smoothed))\n\n        offset = max(12, width // 40)\n        left_x = (center - offset) % width\n        right_x = (center + offset) % width\n        row = winner.shape[0] // 2\n        left_values = confidence[[first_index, second_index], row, left_x]\n        right_values = confidence[[first_index, second_index], row, right_x]\n        left_camera = pair[int(np.argmax(left_values))]\n        right_camera = pair[int(np.argmax(right_values))]\n        if left_camera == right_camera:\n            right_camera = pair[1] if left_camera == pair[0] else pair[0]\n        geometry[pair] = SeamGeometry(center, left_camera, right_camera)\n    return geometry, winner, coverage\n\n\ndef band_x(center_x: int, half_width: int, width: int) -> Tuple[np.ndarray, np.ndarray]:\n    offsets = np.arange(-half_width, half_width + 1)\n    return (center_x + offsets) % width, offsets\n\n\ndef band_alpha(offsets: np.ndarray, half_width: int, transition_px: int) -> np.ndarray:\n    if transition_px <= 0:\n        return np.ones_like(offsets, dtype=np.float32)\n    distance_to_edge = half_width - np.abs(offsets)\n    alpha = np.clip(distance_to_edge / float(transition_px), 0.0, 1.0)\n    return (0.5 - 0.5 * np.cos(math.pi * alpha)).astype(np.float32)\n\n\ndef localize_warps(\n    warps_by_radius,\n    pair_radii: Mapping[Pair, float],\n    seams: Mapping[Pair, SeamGeometry],\n    far_radius_m: float,\n    half_width: int,\n    transition_px: int,\n) -> Tuple[Dict[str, np.ndarray], Dict[str, np.ndarray]]:\n    _, far_images, far_masks = warps_by_radius[far_radius_m]\n    images = {\n        camera: far_images[camera].astype(np.float32).copy()\n        for camera in base.CAMERA_ORDER\n    }\n    mask_strength = {\n        camera: (far_masks[camera] > 0).astype(np.float32)\n        for camera in base.CAMERA_ORDER\n    }\n    width = base.PANO_WIDTH\n    for pair, radius in pair_radii.items():\n        if radius == far_radius_m:\n            continue\n        _, selected_images, selected_masks = warps_by_radius[radius]\n        xs, offsets = band_x(seams[pair].center_x, half_width, width)\n        alpha = band_alpha(offsets, half_width, transition_px)[None, :, None]\n        for camera in pair:\n            old_valid = mask_strength[camera][:, xs, None]\n            new_valid = (selected_masks[camera][:, xs] > 0).astype(np.float32)[\n                ..., None\n            ]\n            # A near-radius projection can lose a thin strip of coverage at the\n            # ERP boundary.  Only replace the far layer where the near layer is\n            # valid; otherwise retain the valid far projection instead of\n            # creating a black wedge.\n            effective_alpha = alpha * new_valid\n            old_weight = (1.0 - effective_alpha) * old_valid\n            new_weight = effective_alpha\n            total = old_weight + new_weight\n            mixed = np.divide(\n                images[camera][:, xs] * old_weight\n                + selected_images[camera][:, xs].astype(np.float32) * new_weight,\n                total,\n                out=np.zeros_like(images[camera][:, xs]),\n                where=total > 1e-6,\n            )\n            images[camera][:, xs] = mixed\n            mask_strength[camera][:, xs] = np.clip(total[..., 0], 0.0, 1.0)\n    return (\n        {camera: np.clip(image, 0, 255).astype(np.uint8) for camera, image in images.items()},\n        {\n            camera: (mask_strength[camera] > 0.25).astype(np.uint8) * 255\n            for camera in base.CAMERA_ORDER\n        },\n    )\n\n\ndef seam_cost(\n    first: np.ndarray,\n    second: np.ndarray,\n    first_mask: np.ndarray,\n    second_mask: np.ndarray,\n    xs: np.ndarray,\n    foreground_context_px: int = 18,\n    foreground_context_weight: float = 1.25,\n) -> Tuple[np.ndarray, np.ndarray]:\n    first_band = first[:, xs].astype(np.float32)\n    second_band = second[:, xs].astype(np.float32)\n    color = np.mean(np.abs(first_band - second_band), axis=2) / 255.0\n    first_gray = cv2.cvtColor(first_band.astype(np.uint8), cv2.COLOR_BGR2GRAY)\n    second_gray = cv2.cvtColor(second_band.astype(np.uint8), cv2.COLOR_BGR2GRAY)\n    first_gradient = cv2.magnitude(\n        cv2.Sobel(first_gray, cv2.CV_32F, 1, 0, ksize=3),\n        cv2.Sobel(first_gray, cv2.CV_32F, 0, 1, ksize=3),\n    )\n    second_gradient = cv2.magnitude(\n        cv2.Sobel(second_gray, cv2.CV_32F, 1, 0, ksize=3),\n        cv2.Sobel(second_gray, cv2.CV_32F, 0, 1, ksize=3),\n    )\n    gradient_difference = np.abs(first_gradient - second_gradient) / 1020.0\n    content_edge = np.maximum(first_gradient, second_gradient) / 1020.0\n    # Expand disagreement around silhouettes.  A one-pixel minimum through a\n    # person or landing gear is still objectionable, so the seam should route\n    # around the whole inconsistent structure instead of tracing its edge.\n    expanded_mismatch = cv2.GaussianBlur(\n        color, (0, 0), sigmaX=4.0, sigmaY=4.0\n    )\n    if foreground_context_px > 0 and foreground_context_weight > 0.0:\n        # A close, low-texture object (hair and clothing are common examples)\n        # may have low error inside the object but large error on both of its\n        # displaced silhouettes.  Looking only at the current pixel makes the\n        # minimum-cost path run through the object or trace one silhouette,\n        # which can erase it when ownership changes.  A horizontally elongated\n        # max filter marks the whole parallax structure as expensive and lets\n        # the seam go around it.\n        horizontal = 2 * foreground_context_px + 1\n        vertical_radius = max(2, foreground_context_px // 3)\n        vertical = 2 * vertical_radius + 1\n        kernel = cv2.getStructuringElement(\n            cv2.MORPH_ELLIPSE, (horizontal, vertical)\n        )\n        foreground_context = cv2.dilate(color, kernel)\n    else:\n        foreground_context = np.zeros_like(color)\n    valid = (first_mask[:, xs] > 0) & (second_mask[:, xs] > 0)\n    return (\n        color\n        + 0.75 * expanded_mismatch\n        + foreground_context_weight * foreground_context\n        + 0.30 * gradient_difference\n        + 0.35 * content_edge,\n        valid,\n    )\n\n\ndef photometric_radius_fallbacks(\n    estimates: Mapping[Pair, PairEstimate],\n    warps_by_radius,\n    seams: Mapping[Pair, SeamGeometry],\n    layers_m: Sequence[float],\n    half_width: int,\n    min_matches: int,\n    foreground_context_px: int,\n    foreground_context_weight: float,\n    min_relative_coverage: float,\n) -> Dict[Pair, Tuple[float, Mapping[float, float]]]:\n    """Select a depth for textureless overlaps using robust image disagreement.\n\n    Feature matching often returns no points on a close head or plain clothing.\n    Falling back to the far layer in that case is especially harmful.  All\n    projection layers are already available, so compare the two warped views\n    directly and keep candidates whose overlap coverage is close to the\n    best-covered layer.\n    """\n\n    fallbacks: Dict[Pair, Tuple[float, Mapping[float, float]]] = {}\n    width = base.PANO_WIDTH\n    for pair, estimate in estimates.items():\n        if estimate.match_count >= min_matches:\n            continue\n        xs, _ = band_x(seams[pair].center_x, half_width, width)\n        scores: Dict[float, float] = {}\n        coverages: Dict[float, float] = {}\n        for radius in layers_m:\n            _, images, masks = warps_by_radius[radius]\n            cost, valid = seam_cost(\n                images[pair[0]],\n                images[pair[1]],\n                masks[pair[0]],\n                masks[pair[1]],\n                xs,\n                foreground_context_px,\n                foreground_context_weight,\n            )\n            values = cost[valid]\n            coverages[radius] = float(np.mean(valid))\n            scores[radius] = (\n                float(np.median(values)) if values.size else float("inf")\n            )\n        maximum_coverage = max(coverages.values(), default=0.0)\n        required_coverage = min_relative_coverage * maximum_coverage\n        usable_scores = {\n            radius: (\n                score\n                if coverages[radius] >= required_coverage\n                else float("inf")\n            )\n            for radius, score in scores.items()\n        }\n        candidate = min(usable_scores, key=usable_scores.get)\n        fallbacks[pair] = (candidate, usable_scores)\n    return fallbacks\n\n\ndef minimum_cost_vertical_path(\n    cost: np.ndarray,\n    valid: np.ndarray,\n    max_step: int,\n    center_prior: float,\n    temporal_target: Optional[np.ndarray] = None,\n    temporal_prior: float = 0.0,\n) -> np.ndarray:\n    height, width = cost.shape\n    coordinates = np.linspace(-1.0, 1.0, width)\n    penalized = cost + center_prior * coordinates[None, :] ** 2\n    if temporal_target is not None and temporal_prior > 0.0:\n        columns = np.arange(width)[None, :]\n        temporal_distance = (columns - temporal_target[:, None]) / max(width - 1, 1)\n        penalized += temporal_prior * temporal_distance.astype(np.float32) ** 2\n    finite_cost = penalized[valid]\n    fallback = float(np.median(finite_cost) + 2.0) if finite_cost.size else 10.0\n    penalized = np.where(valid, penalized, fallback)\n    dp = np.empty_like(penalized, dtype=np.float32)\n    back = np.zeros((height, width), dtype=np.int16)\n    dp[0] = penalized[0]\n    columns = np.arange(width)\n    for row in range(1, height):\n        candidates = []\n        predecessors = []\n        for shift in range(-max_step, max_step + 1):\n            previous = np.clip(columns + shift, 0, width - 1)\n            candidates.append(dp[row - 1, previous])\n            predecessors.append(previous)\n        candidate_stack = np.stack(candidates, axis=0)\n        choice = np.argmin(candidate_stack, axis=0)\n        predecessor_stack = np.stack(predecessors, axis=0)\n        back[row] = predecessor_stack[choice, columns]\n        dp[row] = penalized[row] + candidate_stack[choice, columns]\n    path = np.empty(height, dtype=np.int32)\n    path[-1] = int(np.argmin(dp[-1]))\n    for row in range(height - 1, 0, -1):\n        path[row - 1] = int(back[row, path[row]])\n    return path\n\n\ndef dynamic_seam_weights(\n    images: Mapping[str, np.ndarray],\n    masks: Mapping[str, np.ndarray],\n    seams: Mapping[Pair, SeamGeometry],\n    reference_owner: np.ndarray,\n    coverage: np.ndarray,\n    half_width: int,\n    feather_px: float,\n    max_step: int,\n    center_prior: float,\n    previous_paths: Optional[Mapping[Pair, np.ndarray]] = None,\n    temporal_prior: float = 0.0,\n    temporal_max_shift_px: int = 0,\n    foreground_context_px: int = 18,\n    foreground_context_weight: float = 1.25,\n) -> Tuple[np.ndarray, Dict[Pair, np.ndarray]]:\n    owner = reference_owner.copy()\n    paths = {}\n    width = base.PANO_WIDTH\n    for pair, geometry in seams.items():\n        xs, offsets = band_x(geometry.center_x, half_width, width)\n        cost, valid = seam_cost(\n            images[pair[0]],\n            images[pair[1]],\n            masks[pair[0]],\n            masks[pair[1]],\n            xs,\n            foreground_context_px,\n            foreground_context_weight,\n        )\n        temporal_target = None\n        if previous_paths is not None and pair in previous_paths:\n            previous = previous_paths[pair]\n            temporal_target = np.argmin(\n                circular_distance(\n                    xs[None, :].astype(np.float64),\n                    previous[:, None].astype(np.float64),\n                    width,\n                ),\n                axis=1,\n            )\n        path = minimum_cost_vertical_path(\n            cost,\n            valid,\n            max_step,\n            center_prior,\n            temporal_target,\n            temporal_prior,\n        )\n        if (\n            previous_paths is not None\n            and pair in previous_paths\n            and temporal_max_shift_px > 0\n        ):\n            proposed_global = xs[path]\n            previous_global = previous_paths[pair]\n            signed_delta = (\n                proposed_global.astype(np.int32)\n                - previous_global.astype(np.int32)\n                + width // 2\n            ) % width - width // 2\n            limited_global = (\n                previous_global\n                + np.clip(\n                    signed_delta,\n                    -temporal_max_shift_px,\n                    temporal_max_shift_px,\n                )\n            ) % width\n            path = np.argmin(\n                circular_distance(\n                    xs[None, :].astype(np.float64),\n                    limited_global[:, None].astype(np.float64),\n                    width,\n                ),\n                axis=1,\n            )\n        paths[pair] = xs[path]\n        left_index = base.CAMERA_ORDER.index(geometry.left_camera)\n        right_index = base.CAMERA_ORDER.index(geometry.right_camera)\n        pair_indices = {\n            base.CAMERA_ORDER.index(pair[0]),\n            base.CAMERA_ORDER.index(pair[1]),\n        }\n        for row in range(base.PANO_HEIGHT):\n            local_owner = np.where(\n                np.arange(len(xs)) <= path[row], left_index, right_index\n            )\n            eligible = (\n                np.isin(owner[row, xs], list(pair_indices))\n                & coverage[row, xs]\n            )\n            owner[row, xs[eligible]] = local_owner[eligible]\n\n    weights = []\n    for index, camera in enumerate(base.CAMERA_ORDER):\n        hard = ((owner == index) & (masks[camera] > 0) & coverage).astype(np.float32)\n        weight = base._horizontal_wrap_blur(hard, feather_px)\n        weights.append(weight * (masks[camera] > 0).astype(np.float32))\n    weights = np.stack(weights, axis=0)\n    total = np.sum(weights, axis=0, keepdims=True)\n    weights = np.divide(\n        weights, total, out=np.zeros_like(weights), where=total > 1e-6\n    )\n    return weights, paths\n\n\ndef multiband_blend(\n    images: Mapping[str, np.ndarray],\n    masks: Mapping[str, np.ndarray],\n    narrow_weights: np.ndarray,\n    wide_feather_px: float,\n    low_frequency_sigma_px: float,\n) -> np.ndarray:\n    hard_owner = np.argmax(narrow_weights, axis=0)\n    wide = []\n    for index, camera in enumerate(base.CAMERA_ORDER):\n        hard = ((hard_owner == index) & (masks[camera] > 0)).astype(np.float32)\n        wide.append(\n            base._horizontal_wrap_blur(hard, wide_feather_px)\n            * (masks[camera] > 0).astype(np.float32)\n        )\n    wide_weights = np.stack(wide, axis=0)\n    total = np.sum(wide_weights, axis=0, keepdims=True)\n    wide_weights = np.divide(\n        wide_weights,\n        total,\n        out=np.zeros_like(wide_weights),\n        where=total > 1e-6,\n    )\n    low_images = {\n        camera: adaptive.normalized_lowpass(\n            images[camera], masks[camera], low_frequency_sigma_px\n        )\n        for camera in base.CAMERA_ORDER\n    }\n    high_images = {\n        camera: images[camera].astype(np.float32) - low_images[camera]\n        for camera in base.CAMERA_ORDER\n    }\n    panorama = adaptive.weighted_blend(low_images, wide_weights)\n    panorama += adaptive.weighted_blend(high_images, narrow_weights)\n    # Match the final ERP orientation used by stitch_new_uav.py: upright and\n    # with physical left/right preserved in the displayed panorama.\n    return cv2.flip(np.clip(panorama, 0, 255).astype(np.uint8), -1)\n\n\ndef draw_debug_seams(\n    panorama: np.ndarray,\n    paths: Mapping[Pair, np.ndarray],\n    pair_radii: Mapping[Pair, float],\n) -> np.ndarray:\n    result = panorama.copy()\n    colors = ((0, 255, 255), (0, 255, 0), (255, 255, 0), (255, 0, 255))\n    for color, pair in zip(colors, base.ADJACENT_CAMERA_PAIRS):\n        path = paths[pair]\n        display_x = base.PANO_WIDTH - 1 - path\n        points = np.column_stack(\n            (display_x, base.PANO_HEIGHT - 1 - np.arange(base.PANO_HEIGHT))\n        ).astype(np.int32)\n        for start in range(0, len(points) - 1):\n            if abs(int(points[start + 1, 0]) - int(points[start, 0])) < base.PANO_WIDTH // 2:\n                cv2.line(result, tuple(points[start]), tuple(points[start + 1]), color, 1)\n        label = f"{pair[0]}|{pair[1]} {pair_radii[pair]:g}m"\n        cv2.putText(\n            result,\n            label,\n            (\n                int(display_x[base.PANO_HEIGHT // 2]) % base.PANO_WIDTH,\n                20 + 18 * list(base.ADJACENT_CAMERA_PAIRS).index(pair),\n            ),\n            cv2.FONT_HERSHEY_SIMPLEX,\n            0.35,\n            color,\n            1,\n            cv2.LINE_AA,\n        )\n    return result\n\n\ndef select_frames(frames, args):\n    if args.timestamps:\n        selected = []\n        seen = set()\n        for timestamp in args.timestamps:\n            frame = min(frames, key=lambda item: abs(item.timestamp - timestamp))\n            if frame.timestamp not in seen:\n                selected.append(frame)\n                seen.add(frame.timestamp)\n        return sorted(selected, key=lambda item: item.timestamp)\n    filtered = [\n        frame\n        for frame in frames\n        if (args.start_timestamp is None or frame.timestamp >= args.start_timestamp)\n        and (args.end_timestamp is None or frame.timestamp <= args.end_timestamp)\n    ]\n    selected = filtered[:: args.stride]\n    if args.max_frames is not None:\n        selected = selected[: args.max_frames]\n    return selected\n\n\ndef build_parser() -> argparse.ArgumentParser:\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("--input-dir", type=Path, default=base.DEFAULT_INPUT_DIR)\n    parser.add_argument(\n        "--cam-mapping",\n        type=Path,\n        help=(\n            "Optional text file containing \'topic -> logical_camera\' lines. "\n            "Use this when a recording has different ROS camera wiring."\n        ),\n    )\n    parser.add_argument("--calib-dir", type=Path, default=base.DEFAULT_CALIB_DIR)\n    parser.add_argument(\n        "--calib-topic-mapping",\n        type=Path,\n        help=(\n            "Optional topic-to-logical-camera mapping used to discover Kalibr "\n            "YAML files from their rostopic fields. This is separate from "\n            "--cam-mapping because recorded image wiring may differ from the "\n            "calibration recording."\n        ),\n    )\n    parser.add_argument(\n        "--refinement-path", type=Path, default=base.DEFAULT_REFINEMENT_PATH\n    )\n    parser.add_argument(\n        "--color-calibration-path",\n        type=Path,\n        default=adaptive.DEFAULT_COLOR_CALIBRATION_PATH,\n    )\n    parser.add_argument("--no-refinement", action="store_true")\n    parser.add_argument("--output-dir", type=Path, default=DEFAULT_OUTPUT_DIR)\n    parser.add_argument("--timestamps", type=parse_timestamps)\n    parser.add_argument("--start-timestamp", type=float)\n    parser.add_argument("--end-timestamp", type=float)\n    parser.add_argument("--max-frames", type=int)\n    parser.add_argument("--stride", type=int, default=1)\n    parser.add_argument("--max-sync-gap", type=float, default=0.02)\n    parser.add_argument("--layers", type=parse_float_list, default=DEFAULT_LAYERS_M)\n    parser.add_argument("--default-radius", type=float, default=30.0)\n    parser.add_argument("--radius-update-interval", type=int, default=5)\n    parser.add_argument("--feature-scale", type=float, default=0.5)\n    parser.add_argument("--max-features", type=int, default=2000)\n    parser.add_argument("--score-quantile", type=float, default=0.65)\n    parser.add_argument("--match-geometry-max-error-px", type=float, default=24.0)\n    parser.add_argument("--min-pair-matches", type=int, default=8)\n    parser.add_argument("--switch-margin-px", type=float, default=0.18)\n    parser.add_argument("--switch-confirmations", type=int, default=2)\n    parser.add_argument(\n        "--fast-switch-margin-px",\n        type=float,\n        help=(\n            "Optional isolated strategy: a feature-supported candidate whose "\n            "score improves the current radius by at least this many pixels "\n            "switches immediately; all other changes retain the normal "\n            "confirmation count. Photometric fallbacks never use fast switching."\n        ),\n    )\n    parser.add_argument("--seam-band-half-width", type=int, default=72)\n    parser.add_argument("--band-transition-px", type=int, default=12)\n    parser.add_argument("--seam-feather-px", type=float, default=3.0)\n    parser.add_argument("--wide-seam-feather-px", type=float, default=16.0)\n    parser.add_argument("--low-frequency-sigma-px", type=float, default=8.0)\n    parser.add_argument("--seam-max-step", type=int, default=2)\n    parser.add_argument("--seam-center-prior", type=float, default=0.10)\n    parser.add_argument("--seam-temporal-prior", type=float, default=0.20)\n    parser.add_argument("--seam-temporal-max-shift-px", type=int, default=16)\n    parser.add_argument("--foreground-context-px", type=int, default=18)\n    parser.add_argument(\n        "--foreground-context-weight",\n        type=float,\n        default=0.0,\n        help=(\n            "Experimental symmetric foreground-avoidance cost. Keep at 0 for "\n            "moving people: without semantic ownership it may route around the "\n            "wrong side of an object."\n        ),\n    )\n    parser.add_argument("--photometric-switch-margin", type=float, default=0.006)\n    parser.add_argument("--photometric-min-relative-coverage", type=float, default=0.82)\n    parser.add_argument("--exposure-update-interval", type=int, default=10)\n    parser.add_argument("--exposure-smoothing-alpha", type=float, default=0.25)\n    parser.add_argument("--no-exposure-compensation", action="store_true")\n    parser.add_argument("--write-fixed-comparison", action="store_true")\n    parser.add_argument("--debug", action="store_true")\n    return parser\n\n\ndef validate_args(args) -> None:\n    if args.default_radius not in args.layers:\n        raise ValueError("--default-radius must be one of --layers")\n    if args.radius_update_interval <= 0 or args.exposure_update_interval <= 0:\n        raise ValueError("update intervals must be positive")\n    if args.stride <= 0:\n        raise ValueError("--stride must be positive")\n    if args.max_frames is not None and args.max_frames <= 0:\n        raise ValueError("--max-frames must be positive")\n    if not 0.5 <= args.score_quantile <= 0.9:\n        raise ValueError("--score-quantile must be in [0.5, 0.9]")\n    if args.min_pair_matches < 4:\n        raise ValueError("--min-pair-matches must be at least 4")\n    if args.match_geometry_max_error_px <= 0.0:\n        raise ValueError("--match-geometry-max-error-px must be positive")\n    if args.switch_confirmations <= 0:\n        raise ValueError("--switch-confirmations must be positive")\n    if (\n        args.fast_switch_margin_px is not None\n        and args.fast_switch_margin_px < args.switch_margin_px\n    ):\n        raise ValueError(\n            "--fast-switch-margin-px must be at least --switch-margin-px"\n        )\n    if args.seam_band_half_width < 10:\n        raise ValueError("--seam-band-half-width must be at least 10")\n    if args.seam_temporal_max_shift_px < 0:\n        raise ValueError("--seam-temporal-max-shift-px must be non-negative")\n    if args.foreground_context_px < 0:\n        raise ValueError("--foreground-context-px must be non-negative")\n    if args.foreground_context_weight < 0.0:\n        raise ValueError("--foreground-context-weight must be non-negative")\n    if args.photometric_switch_margin < 0.0:\n        raise ValueError("--photometric-switch-margin must be non-negative")\n    if not 0.5 <= args.photometric_min_relative_coverage <= 1.0:\n        raise ValueError(\n            "--photometric-min-relative-coverage must be in [0.5, 1.0]"\n        )\n    if not 0.0 < args.exposure_smoothing_alpha <= 1.0:\n        raise ValueError("--exposure-smoothing-alpha must be in (0, 1]")\n\n\ndef main() -> None:\n    args = build_parser().parse_args()\n    validate_args(args)\n    if args.calib_topic_mapping is not None:\n        # Runtime import avoids coupling the stable desktop implementation to\n        # the NX module unless rostopic-based calibration discovery is needed.\n        from new_uav import stitch_new_uav_orin_realtime as realtime\n\n        calibration_mapping = base.load_topic_to_camera(\n            args.calib_topic_mapping.resolve()\n        )\n        calibrations, _ = realtime.load_discovered_calibrations(\n            args.calib_dir.resolve(), calibration_mapping\n        )\n        realtime.validate_extrinsics(calibrations)\n    else:\n        calibrations = base.load_all_calibrations(args.calib_dir.resolve())\n    refinement = None\n    if not args.no_refinement:\n        refinement = adaptive.load_refinement(args.refinement_path.resolve())\n    static_chroma = adaptive.load_static_chroma_gains(\n        args.color_calibration_path.resolve()\n    )\n    mapping_path = args.cam_mapping.resolve() if args.cam_mapping else None\n    topic_to_camera = base.load_topic_to_camera(mapping_path)\n    indices = base.build_image_indices(args.input_dir.resolve(), topic_to_camera)\n    frames = base.synchronize_frames(indices, args.max_sync_gap)\n    selected = select_frames(frames, args)\n    if not selected:\n        raise RuntimeError("No synchronized frames selected")\n\n    output_dir = args.output_dir.resolve()\n    result_dir = output_dir / "multiseam"\n    fixed_dir = output_dir / f"fixed_{args.default_radius:g}m"\n    debug_dir = output_dir / "debug"\n    result_dir.mkdir(parents=True, exist_ok=True)\n    if args.write_fixed_comparison:\n        fixed_dir.mkdir(parents=True, exist_ok=True)\n    if args.debug:\n        debug_dir.mkdir(parents=True, exist_ok=True)\n\n    print(f"Building projection layers: {args.layers}")\n    bank = adaptive.RadiusLUTBank(\n        calibrations,\n        refinement,\n        args.layers,\n        args.seam_feather_px,\n        args.low_frequency_sigma_px,\n        args.wide_seam_feather_px,\n        exposure_compensation=not args.no_exposure_compensation,\n    )\n    far_radius = max(args.layers)\n    far_luts = bank.stitchers[far_radius].luts\n    seams, reference_owner, coverage = find_seam_geometry(far_luts)\n    print(\n        "Reference seams: "\n        + ", ".join(\n            f"{first}|{second}@x={seams[(first, second)].center_x}"\n            for first, second in base.ADJACENT_CAMERA_PAIRS\n        )\n    )\n    estimator = PerSeamRadiusEstimator(\n        calibrations,\n        refinement,\n        args.layers,\n        args.feature_scale,\n        args.max_features,\n        args.score_quantile,\n        args.match_geometry_max_error_px,\n    )\n    hysteresis = RadiusHysteresis(\n        base.ADJACENT_CAMERA_PAIRS,\n        args.default_radius,\n        args.min_pair_matches,\n        args.switch_margin_px,\n        args.switch_confirmations,\n        args.fast_switch_margin_px,\n    )\n\n    last_estimates: Dict[Pair, PairEstimate] = {}\n    pair_radii = {\n        pair: args.default_radius for pair in base.ADJACENT_CAMERA_PAIRS\n    }\n    smoothed_log_gains = None\n    report_rows: List[Dict[str, object]] = []\n    previous_paths: Optional[Dict[Pair, np.ndarray]] = None\n\n    for index, frame in enumerate(selected):\n        frame_start = time.perf_counter()\n        estimate_ms = 0.0\n        updated = index % args.radius_update_interval == 0\n        if updated:\n            start = time.perf_counter()\n            last_estimates = estimator.estimate(frame)\n            estimate_ms = (time.perf_counter() - start) * 1000.0\n\n        raw_images = bank.read_images(frame.files)\n        start = time.perf_counter()\n        warps_by_radius = {\n            radius: bank.warp(radius, raw_images) for radius in args.layers\n        }\n        warp_ms = (time.perf_counter() - start) * 1000.0\n        if updated:\n            start = time.perf_counter()\n            fallbacks = photometric_radius_fallbacks(\n                last_estimates,\n                warps_by_radius,\n                seams,\n                args.layers,\n                args.seam_band_half_width,\n                args.min_pair_matches,\n                args.foreground_context_px,\n                args.foreground_context_weight,\n                args.photometric_min_relative_coverage,\n            )\n            pair_radii = hysteresis.update(\n                last_estimates,\n                fallbacks,\n                args.photometric_switch_margin,\n            )\n            estimate_ms += (time.perf_counter() - start) * 1000.0\n\n        exposure_ms = 0.0\n        exposure_updated = (\n            not args.no_exposure_compensation\n            and (\n                smoothed_log_gains is None\n                or index % args.exposure_update_interval == 0\n            )\n        )\n        if exposure_updated:\n            start = time.perf_counter()\n            _, reference_images, reference_masks = warps_by_radius[\n                args.default_radius\n            ]\n            gains = adaptive.estimate_exposure_gains(\n                reference_images, reference_masks\n            )\n            gains = adaptive.constrain_gains_to_static_chroma(\n                gains, static_chroma\n            )\n            observed = np.log(gains)\n            if smoothed_log_gains is None:\n                smoothed_log_gains = observed\n            else:\n                alpha = args.exposure_smoothing_alpha\n                smoothed_log_gains = (\n                    (1.0 - alpha) * smoothed_log_gains + alpha * observed\n                )\n            exposure_ms = (time.perf_counter() - start) * 1000.0\n        gains = np.exp(smoothed_log_gains) if smoothed_log_gains is not None else None\n\n        start = time.perf_counter()\n        local_images, local_masks = localize_warps(\n            warps_by_radius,\n            pair_radii,\n            seams,\n            far_radius,\n            args.seam_band_half_width,\n            args.band_transition_px,\n        )\n        if gains is not None:\n            local_images = adaptive.apply_exposure_gains(local_images, gains)\n        narrow_weights, paths = dynamic_seam_weights(\n            local_images,\n            local_masks,\n            seams,\n            reference_owner,\n            coverage,\n            args.seam_band_half_width,\n            args.seam_feather_px,\n            args.seam_max_step,\n            args.seam_center_prior,\n            previous_paths,\n            args.seam_temporal_prior,\n            args.seam_temporal_max_shift_px,\n            args.foreground_context_px,\n            args.foreground_context_weight,\n        )\n        previous_paths = paths\n        panorama = multiband_blend(\n            local_images,\n            local_masks,\n            narrow_weights,\n            args.wide_seam_feather_px,\n            args.low_frequency_sigma_px,\n        )\n        stitch_ms = (time.perf_counter() - start) * 1000.0\n        output_path = result_dir / f"pano_{frame.timestamp:.6f}.jpg"\n        if not cv2.imwrite(str(output_path), panorama):\n            raise RuntimeError(f"Failed to write {output_path}")\n\n        if args.write_fixed_comparison:\n            fixed_radius, fixed_images, fixed_masks = warps_by_radius[\n                args.default_radius\n            ]\n            fixed_panorama, _ = bank.blend(\n                fixed_radius, fixed_images, fixed_masks, gains\n            )\n            fixed_path = fixed_dir / f"pano_{frame.timestamp:.6f}.jpg"\n            if not cv2.imwrite(str(fixed_path), fixed_panorama):\n                raise RuntimeError(f"Failed to write {fixed_path}")\n        if args.debug:\n            debug = draw_debug_seams(panorama, paths, pair_radii)\n            cv2.imwrite(str(debug_dir / f"pano_{frame.timestamp:.6f}_seams.jpg"), debug)\n\n        selected_scores = []\n        far_scores = []\n        match_count = 0\n        pair_report = {}\n        for pair in base.ADJACENT_CAMERA_PAIRS:\n            estimate = last_estimates.get(pair)\n            key = f"{pair[0]}|{pair[1]}"\n            if estimate is None:\n                pair_report[key] = {"radius_m": pair_radii[pair]}\n                continue\n            selected_score = estimate.scores_px[pair_radii[pair]]\n            far_score = estimate.scores_px[far_radius]\n            if np.isfinite(selected_score) and np.isfinite(far_score):\n                selected_scores.append(selected_score)\n                far_scores.append(far_score)\n            match_count += estimate.match_count\n            pair_report[key] = {\n                "radius_m": pair_radii[pair],\n                "raw_radius_m": estimate.raw_radius_m,\n                "matches": estimate.match_count,\n                "selected_score_px": (\n                    round(selected_score, 4) if np.isfinite(selected_score) else None\n                ),\n                "far_score_px": round(far_score, 4) if np.isfinite(far_score) else None,\n            }\n        selected_mean = float(np.mean(selected_scores)) if selected_scores else float("nan")\n        far_mean = float(np.mean(far_scores)) if far_scores else float("nan")\n        total_ms = (time.perf_counter() - frame_start) * 1000.0\n        report_rows.append(\n            {\n                "timestamp": f"{frame.timestamp:.6f}",\n                "updated": int(updated),\n                "pair_radii": json.dumps(\n                    {f"{a}|{b}": pair_radii[(a, b)] for a, b in base.ADJACENT_CAMERA_PAIRS}\n                ),\n                "pair_diagnostics": json.dumps(pair_report),\n                "seam_midpoint_x": json.dumps(\n                    {\n                        f"{a}|{b}": int(paths[(a, b)][base.PANO_HEIGHT // 2])\n                        for a, b in base.ADJACENT_CAMERA_PAIRS\n                    }\n                ),\n                "match_count": match_count if updated else "",\n                "far_reprojection_score_px": (\n                    f"{far_mean:.4f}" if np.isfinite(far_mean) else ""\n                ),\n                "selected_reprojection_score_px": (\n                    f"{selected_mean:.4f}" if np.isfinite(selected_mean) else ""\n                ),\n                "score_improvement_px": (\n                    f"{far_mean - selected_mean:.4f}"\n                    if np.isfinite(far_mean) and np.isfinite(selected_mean)\n                    else ""\n                ),\n                "estimate_ms": f"{estimate_ms:.2f}",\n                "warp_ms": f"{warp_ms:.2f}",\n                "exposure_ms": f"{exposure_ms:.2f}",\n                "stitch_ms": f"{stitch_ms:.2f}",\n                "total_ms": f"{total_ms:.2f}",\n                "max_sync_gap_ms": f"{frame.max_sync_gap * 1000.0:.3f}",\n            }\n        )\n        print(\n            f"[{index + 1}/{len(selected)}] {output_path.name}: "\n            f"radii={{{\', \'.join(f\'{a}|{b}:{pair_radii[(a,b)]:g}\' for a,b in base.ADJACENT_CAMERA_PAIRS)}}}, "\n            f"score={selected_mean:.2f}/{far_mean:.2f}px, total={total_ms:.1f}ms"\n        )\n\n    report_path = output_dir / "multiseam_report.csv"\n    with report_path.open("w", newline="", encoding="utf-8") as handle:\n        writer = csv.DictWriter(handle, fieldnames=list(report_rows[0]))\n        writer.writeheader()\n        writer.writerows(report_rows)\n    print(f"Saved report: {report_path}")\n\n\n', 'stitch_new_uav_multiseam.py', "exec"), multiseam_namespace, multiseam_namespace)
