exec(compile('#!/usr/bin/env python3\n"""CUDA-accelerated four-fisheye stitching for Jetson Orin NX.\n\nThe projection and blend path uses the CUDA-enabled PyTorch distributed for\nJetson instead of OpenCV\'s optional Python CUDA bindings.  Four fisheye images\nare uploaded as one batch, projected by one ``grid_sample`` call, exposure\ncorrected, and blended on the GPU.  The dynamic seam is evaluated sparsely and\nonly downloads the four small ERP warps when a seam update is required.\n\nThe calibration, camera-wiring and output orientation contracts are identical\nto ``stitch_new_uav_orin_realtime.py``.  Legacy image-alignment refinement is\ndisabled unless ``--refinement-path`` is explicitly supplied.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport json\nimport math\nimport sys\nimport time\nfrom dataclasses import asdict, dataclass\nfrom pathlib import Path\nfrom typing import Any, Dict, Mapping, Optional, Sequence, Tuple\n\nimport cv2\nimport numpy as np\n\n\nSCRIPT_DIR = Path(__file__).resolve().parent\nPROJECT_ROOT = SCRIPT_DIR.parent\nsys.path.insert(0, str(PROJECT_ROOT))\n\n\n\nDEFAULT_OUTPUT_DIR = (\n    PROJECT_ROOT / "output_panos/indoor_data_new/orin_cuda_new_extrinsics"\n)\nPair = Tuple[str, str]\n\n\n@dataclass\nclass CudaRuntimeDiagnostics:\n    timestamp: float\n    backend: str\n    precision: str\n    seam_updated: bool\n    quality_triggered: bool\n    seam_score_before: float\n    seam_score_after: float\n    read_ms: float\n    upload_ms: float\n    remap_ms: float\n    exposure_ms: float\n    seam_ms: float\n    blend_ms: float\n    download_ms: float\n    write_ms: float\n    total_ms: float\n    max_sync_gap_ms: float\n\n\ndef import_torch() -> Any:\n    try:\n        import torch\n    except ImportError as exc:\n        raise RuntimeError(\n            "PyTorch is not installed. On Jetson, install NVIDIA\'s Jetson "\n            "PyTorch wheel matching the installed JetPack version; do not "\n            "install the generic x86 PyPI wheel."\n        ) from exc\n    return torch\n\n\ndef cuda_summary(torch: Any) -> Dict[str, object]:\n    available = bool(torch.cuda.is_available())\n    summary: Dict[str, object] = {\n        "torch_version": str(torch.__version__),\n        "cuda_available": available,\n        "torch_cuda_version": str(torch.version.cuda),\n        "device_count": int(torch.cuda.device_count()) if available else 0,\n    }\n    if available:\n        device = torch.cuda.current_device()\n        properties = torch.cuda.get_device_properties(device)\n        summary.update(\n            {\n                "device_index": int(device),\n                "device_name": str(properties.name),\n                "compute_capability": (\n                    f"{properties.major}.{properties.minor}"\n                ),\n                "total_memory_mib": int(\n                    properties.total_memory / (1024 * 1024)\n                ),\n            }\n        )\n    return summary\n\n\ndef resolve_backend(\n    requested: str,\n) -> Tuple[str, Optional[Any], Optional[Any]]:\n    if requested == "cpu":\n        return "cpu-reference", None, None\n\n    try:\n        torch = import_torch()\n    except RuntimeError:\n        if requested == "auto":\n            print(\n                "WARNING: PyTorch is unavailable; using the CPU reference "\n                "pipeline. Use --device cuda on NX to make this a hard error."\n            )\n            return "cpu-reference", None, None\n        raise\n\n    if requested == "torch-cpu":\n        return "torch-cpu", torch, torch.device("cpu")\n    if torch.cuda.is_available():\n        return "torch-cuda", torch, torch.device("cuda")\n    if requested == "cuda":\n        raise RuntimeError(\n            "CUDA was requested but torch.cuda.is_available() is False. "\n            "Verify that this is NVIDIA\'s Jetson PyTorch build and that its "\n            "CUDA version matches JetPack."\n        )\n    print(\n        "WARNING: CUDA is unavailable; using the CPU reference pipeline. "\n        "This fallback is for correctness only, not NX performance."\n    )\n    return "cpu-reference", None, None\n\n\ndef gaussian_kernel_1d(\n    torch: Any, sigma: float, device: Any, dtype: Any\n) -> Tuple[Any, int]:\n    radius = max(1, int(math.ceil(3.0 * sigma)))\n    positions = torch.arange(\n        -radius, radius + 1, device=device, dtype=torch.float32\n    )\n    kernel = torch.exp(-0.5 * (positions / sigma) ** 2)\n    kernel /= kernel.sum()\n    return kernel.to(dtype=dtype), radius\n\n\ndef wide_weights_from_narrow(\n    narrow_weights: np.ndarray,\n    masks: Mapping[str, np.ndarray],\n    feather_px: float,\n) -> np.ndarray:\n    hard_owner = np.argmax(narrow_weights, axis=0)\n    wide = []\n    for index, camera in enumerate(base.CAMERA_ORDER):\n        hard = (\n            (hard_owner == index) & (masks[camera] > 0)\n        ).astype(np.float32)\n        wide.append(\n            base._horizontal_wrap_blur(hard, feather_px)\n            * (masks[camera] > 0).astype(np.float32)\n        )\n    result = np.stack(wide, axis=0)\n    total = np.sum(result, axis=0, keepdims=True)\n    return np.divide(\n        result,\n        total,\n        out=np.zeros_like(result),\n        where=total > 1e-6,\n    )\n\n\nclass TorchPanoramaStitcher:\n    """Persistent batched projection and blend state on CUDA."""\n\n    def __init__(\n        self,\n        torch: Any,\n        device: Any,\n        calibrations: Mapping[str, base.CameraCalibration],\n        refinement: Optional[Mapping[str, object]],\n        valid_radius_scale: float,\n        exposure_update_interval: int,\n        exposure_smoothing_alpha: float,\n        exposure_sample_stride: int,\n        static_chroma_gains: np.ndarray,\n        seam_update_interval: int,\n        seam_check_interval: int,\n        seam_quality_trigger: float,\n        seam_band_half_width: int,\n        seam_feather_px: float,\n        seam_max_step: int,\n        seam_center_prior: float,\n        seam_temporal_prior: float,\n        seam_temporal_max_shift_px: int,\n        exposure_compensation: bool,\n        blend_mode: str,\n        wide_seam_feather_px: float,\n        low_frequency_sigma_px: float,\n        precision: str,\n    ) -> None:\n        self.torch = torch\n        self.F = torch.nn.functional\n        self.device = device\n        self.is_cuda = device.type == "cuda"\n        self.backend = "torch-cuda" if self.is_cuda else "torch-cpu"\n        self.precision = precision if self.is_cuda else "fp32"\n        self.dtype = (\n            torch.float16\n            if self.precision == "fp16"\n            else torch.float32\n        )\n        if self.is_cuda:\n            torch.backends.cudnn.benchmark = True\n            torch.backends.cuda.matmul.allow_tf32 = True\n            torch.backends.cudnn.allow_tf32 = True\n\n        base.FISHEYE_VALID_RADIUS_SCALE = valid_radius_scale\n        geometry_stitcher = base.NewUAVStitcher(\n            calibrations,\n            seam_feather_px=seam_feather_px,\n            exposure_compensation=False,\n            refinement=refinement,\n        )\n        self.calibrations = calibrations\n        self.luts = geometry_stitcher.luts\n        self.masks = {\n            camera: self.luts[camera][2] for camera in base.CAMERA_ORDER\n        }\n        self.seams, self.reference_owner, self.coverage = (\n            multiseam.find_seam_geometry(self.luts)\n        )\n        self.weights = realtime.initial_weights(self.luts)\n        self.paths: Optional[Dict[Pair, np.ndarray]] = None\n        self.path_tensors: Dict[Pair, Any] = {}\n        self.last_residuals: Dict[str, float] = {}\n        self.last_seam_score = float("inf")\n        self.log_gains: Optional[np.ndarray] = None\n        self.static_chroma_gains = static_chroma_gains\n        self.exposure_compensation = exposure_compensation\n        self.exposure_update_interval = exposure_update_interval\n        self.exposure_smoothing_alpha = exposure_smoothing_alpha\n        self.exposure_sample_stride = exposure_sample_stride\n        self.seam_update_interval = seam_update_interval\n        self.seam_check_interval = seam_check_interval\n        self.seam_quality_trigger = seam_quality_trigger\n        self.seam_band_half_width = seam_band_half_width\n        self.seam_feather_px = seam_feather_px\n        self.seam_max_step = seam_max_step\n        self.seam_center_prior = seam_center_prior\n        self.seam_temporal_prior = seam_temporal_prior\n        self.seam_temporal_max_shift_px = seam_temporal_max_shift_px\n        self.blend_mode = blend_mode\n        self.wide_seam_feather_px = wide_seam_feather_px\n        self.low_frequency_sigma_px = low_frequency_sigma_px\n        self.frame_index = 0\n\n        resolutions = {\n            calibrations[camera].resolution for camera in base.CAMERA_ORDER\n        }\n        if len(resolutions) != 1:\n            raise ValueError(\n                "The batched CUDA path requires the four inputs to have the "\n                f"same resolution, got {sorted(resolutions)}"\n            )\n        self.input_width, self.input_height = next(iter(resolutions))\n        grids = []\n        for camera in base.CAMERA_ORDER:\n            map_x, map_y = self.luts[camera][:2]\n            grid_x = 2.0 * map_x / max(self.input_width - 1, 1) - 1.0\n            grid_y = 2.0 * map_y / max(self.input_height - 1, 1) - 1.0\n            grids.append(np.stack((grid_x, grid_y), axis=-1))\n        self.grid = torch.from_numpy(\n            np.ascontiguousarray(np.stack(grids).astype(np.float32))\n        ).to(device=device, dtype=self.dtype)\n\n        mask_stack = np.stack(\n            [\n                (self.masks[camera] > 0).astype(np.float32)\n                for camera in base.CAMERA_ORDER\n            ],\n            axis=0,\n        )[:, None]\n        self.mask_bool = torch.from_numpy(mask_stack > 0).to(device=device)\n        self.mask_float = self.mask_bool.to(dtype=self.dtype)\n        self.rows = torch.arange(\n            base.PANO_HEIGHT, device=device, dtype=torch.long\n        )\n\n        self.narrow_weights: Any = None\n        self.wide_weights: Any = None\n        self._upload_weights(self.weights)\n\n        self.gaussian_kernel: Optional[Any] = None\n        self.gaussian_radius = 0\n        self.lowpass_denominator: Optional[Any] = None\n        if (\n            self.blend_mode == "multiband"\n            and self.low_frequency_sigma_px > 0.0\n        ):\n            self.gaussian_kernel, self.gaussian_radius = gaussian_kernel_1d(\n                torch,\n                self.low_frequency_sigma_px,\n                self.device,\n                self.dtype,\n            )\n            self.lowpass_denominator = self._gaussian_blur(\n                self.mask_float\n            ).clamp_min(1e-4)\n\n        self.cpu_staging: Optional[Any] = None\n        self.cpu_staging_numpy: Optional[np.ndarray] = None\n        self.gpu_input_u8: Optional[Any] = None\n        self.gpu_input_float: Optional[Any] = None\n        if self.is_cuda:\n            shape = (\n                len(base.CAMERA_ORDER),\n                self.input_height,\n                self.input_width,\n                3,\n            )\n            self.cpu_staging = torch.empty(\n                shape, dtype=torch.uint8, pin_memory=True\n            )\n            self.cpu_staging_numpy = self.cpu_staging.numpy()\n            self.gpu_input_u8 = torch.empty(\n                shape, dtype=torch.uint8, device=device\n            )\n            self.gpu_input_float = torch.empty(\n                (\n                    len(base.CAMERA_ORDER),\n                    3,\n                    self.input_height,\n                    self.input_width,\n                ),\n                dtype=self.dtype,\n                device=device,\n            )\n\n    def _read_images(\n        self, files: Mapping[str, Path]\n    ) -> Dict[str, np.ndarray]:\n        images = {}\n        for camera in base.CAMERA_ORDER:\n            image = cv2.imread(str(files[camera]), cv2.IMREAD_COLOR)\n            if image is None:\n                raise RuntimeError(f"Cannot read image: {files[camera]}")\n            expected = self.calibrations[camera].resolution\n            if image.shape[1::-1] != expected:\n                raise ValueError(\n                    f"{files[camera]} has {image.shape[1]}x{image.shape[0]}, "\n                    f"expected {expected[0]}x{expected[1]}"\n                )\n            images[camera] = image\n        return images\n\n    def _upload_inputs(\n        self, raw_images: Mapping[str, np.ndarray]\n    ) -> Any:\n        if self.is_cuda:\n            assert self.cpu_staging_numpy is not None\n            assert self.cpu_staging is not None\n            assert self.gpu_input_u8 is not None\n            assert self.gpu_input_float is not None\n            for index, camera in enumerate(base.CAMERA_ORDER):\n                np.copyto(\n                    self.cpu_staging_numpy[index], raw_images[camera]\n                )\n            self.gpu_input_u8.copy_(\n                self.cpu_staging, non_blocking=True\n            )\n            self.gpu_input_float.copy_(\n                self.gpu_input_u8.permute(0, 3, 1, 2),\n                non_blocking=True,\n            )\n            return self.gpu_input_float\n        stacked = np.ascontiguousarray(\n            np.stack([raw_images[camera] for camera in base.CAMERA_ORDER])\n        )\n        return (\n            self.torch.from_numpy(stacked)\n            .permute(0, 3, 1, 2)\n            .to(device=self.device, dtype=self.dtype)\n        )\n\n    def _estimate_exposure_gains(self, warped: Any) -> np.ndarray:\n        equations = []\n        channel_deltas = []\n        camera_count = len(base.CAMERA_ORDER)\n        stride = self.exposure_sample_stride\n        minimum_samples = max(24, 300 // (stride * stride))\n        sampled = warped[:, :, ::stride, ::stride].to(\n            dtype=self.torch.float32\n        )\n        sampled_masks = self.mask_bool[:, :, ::stride, ::stride]\n        for first_index in range(camera_count):\n            for second_index in range(first_index + 1, camera_count):\n                overlap = (\n                    sampled_masks[first_index, 0]\n                    & sampled_masks[second_index, 0]\n                )\n                if int(overlap.sum().item()) < minimum_samples:\n                    continue\n                first = sampled[first_index, :, overlap]\n                second = sampled[second_index, :, overlap]\n                deltas = []\n                for channel in range(3):\n                    first_values = first[channel]\n                    second_values = second[channel]\n                    usable = (\n                        (first_values > 12.0)\n                        & (first_values < 243.0)\n                        & (second_values > 12.0)\n                        & (second_values < 243.0)\n                    )\n                    if int(usable.sum().item()) < minimum_samples:\n                        break\n                    delta = self.torch.median(\n                        self.torch.log(second_values[usable])\n                        - self.torch.log(first_values[usable])\n                    )\n                    deltas.append(float(delta.item()))\n                if len(deltas) != 3:\n                    continue\n                row = np.zeros(camera_count, dtype=np.float64)\n                row[first_index] = 1.0\n                row[second_index] = -1.0\n                equations.append(row)\n                channel_deltas.append(deltas)\n\n        anchor = np.zeros(camera_count, dtype=np.float64)\n        anchor[base.CAMERA_ORDER.index(base.BASE_CAMERA)] = 4.0\n        equations.append(anchor)\n        channel_deltas.append([0.0, 0.0, 0.0])\n        log_gains = np.linalg.lstsq(\n            np.asarray(equations),\n            np.asarray(channel_deltas),\n            rcond=None,\n        )[0]\n        observed = np.clip(np.exp(log_gains), 0.67, 1.5)\n        return adaptive.constrain_gains_to_static_chroma(\n            observed, self.static_chroma_gains\n        )\n\n    def _apply_exposure(self, warped: Any) -> Any:\n        if not self.exposure_compensation:\n            return warped\n        if (\n            self.log_gains is None\n            or self.frame_index % self.exposure_update_interval == 0\n        ):\n            observed = self._estimate_exposure_gains(warped)\n            observed_log = np.log(observed)\n            if self.log_gains is None:\n                self.log_gains = observed_log\n            else:\n                alpha = self.exposure_smoothing_alpha\n                self.log_gains = (\n                    (1.0 - alpha) * self.log_gains\n                    + alpha * observed_log\n                )\n        gains = self.torch.from_numpy(\n            np.exp(self.log_gains).astype(np.float32)\n        ).to(device=self.device, dtype=self.dtype)\n        corrected = (warped * gains[:, :, None, None]).clamp(0.0, 255.0)\n        # Match the uint8 exposure boundary in the CPU reference.  Retaining\n        # integer-valued floats also makes CPU/GPU validation deterministic.\n        return corrected.to(self.torch.uint8).to(self.dtype)\n\n    def _upload_weights(self, weights: np.ndarray) -> None:\n        self.weights = weights\n        wide = wide_weights_from_narrow(\n            weights, self.masks, self.wide_seam_feather_px\n        )\n        self.narrow_weights = self.torch.from_numpy(\n            np.ascontiguousarray(weights[:, None].astype(np.float32))\n        ).to(device=self.device, dtype=self.dtype)\n        self.wide_weights = self.torch.from_numpy(\n            np.ascontiguousarray(wide[:, None].astype(np.float32))\n        ).to(device=self.device, dtype=self.dtype)\n\n    def _cache_paths(self) -> None:\n        self.path_tensors = {}\n        if not self.paths:\n            return\n        for pair, path in self.paths.items():\n            self.path_tensors[pair] = self.torch.from_numpy(\n                path.astype(np.int64)\n            ).to(device=self.device)\n\n    def _seam_residuals(\n        self, corrected: Any\n    ) -> Tuple[Dict[str, float], float]:\n        if not self.paths:\n            return {}, float("inf")\n        names = []\n        values = []\n        for pair, path in self.path_tensors.items():\n            first_index = base.CAMERA_ORDER.index(pair[0])\n            second_index = base.CAMERA_ORDER.index(pair[1])\n            valid = (\n                self.mask_bool[first_index, 0, self.rows, path]\n                & self.mask_bool[second_index, 0, self.rows, path]\n            )\n            residual = (\n                corrected[first_index, :, self.rows, path]\n                - corrected[second_index, :, self.rows, path]\n            ).abs().mean(dim=0)\n            usable = residual[valid]\n            value = (\n                self.torch.median(usable)\n                if usable.numel()\n                else self.torch.tensor(\n                    float("nan"), device=self.device\n                )\n            )\n            names.append(f"{pair[0]}|{pair[1]}")\n            values.append(value)\n        host_values = (\n            self.torch.stack(values)\n            .to(dtype=self.torch.float32)\n            .cpu()\n            .numpy()\n        )\n        result = {\n            name: float(value) for name, value in zip(names, host_values)\n        }\n        finite = host_values[np.isfinite(host_values)]\n        score = (\n            float(np.median(finite)) if finite.size else float("inf")\n        )\n        return result, score\n\n    def _download_corrected(self, corrected: Any) -> Dict[str, np.ndarray]:\n        host = (\n            corrected.to(self.torch.uint8)\n            .permute(0, 2, 3, 1)\n            .contiguous()\n            .cpu()\n            .numpy()\n        )\n        return {\n            camera: host[index]\n            for index, camera in enumerate(base.CAMERA_ORDER)\n        }\n\n    def _gaussian_blur(self, tensor: Any) -> Any:\n        if self.gaussian_kernel is None:\n            return tensor\n        channels = tensor.shape[1]\n        radius = self.gaussian_radius\n        kernel_h = self.gaussian_kernel.view(1, 1, 1, -1).repeat(\n            channels, 1, 1, 1\n        )\n        kernel_v = self.gaussian_kernel.view(1, 1, -1, 1).repeat(\n            channels, 1, 1, 1\n        )\n        horizontal = self.F.conv2d(\n            self.F.pad(tensor, (radius, radius, 0, 0), mode="circular"),\n            kernel_h,\n            groups=channels,\n        )\n        return self.F.conv2d(\n            self.F.pad(\n                horizontal, (0, 0, radius, radius), mode="replicate"\n            ),\n            kernel_v,\n            groups=channels,\n        )\n\n    def _blend(self, corrected: Any) -> Any:\n        if self.blend_mode == "fast":\n            panorama = (\n                corrected * self.narrow_weights\n            ).sum(dim=0)\n        elif self.lowpass_denominator is not None:\n            numerator = self._gaussian_blur(\n                corrected * self.mask_float\n            )\n            low = numerator / self.lowpass_denominator\n            high = corrected - low\n            panorama = (\n                low * self.wide_weights\n                + high * self.narrow_weights\n            ).sum(dim=0)\n        else:\n            panorama = (\n                corrected * self.narrow_weights\n            ).sum(dim=0)\n        panorama = panorama.clamp(0.0, 255.0).to(self.torch.uint8)\n        return self.torch.flip(panorama, dims=(1, 2))\n\n    def process(\n        self,\n        inputs: Mapping[str, Any],\n        download_output: bool = True,\n    ) -> Tuple[Any, CudaRuntimeDiagnostics, Dict[str, float]]:\n        torch = self.torch\n        total_start = time.perf_counter()\n        read_start = total_start\n        first_input = next(iter(inputs.values()))\n        if isinstance(first_input, np.ndarray):\n            raw_images = {\n                camera: np.ascontiguousarray(inputs[camera])\n                for camera in base.CAMERA_ORDER\n            }\n            for camera, image in raw_images.items():\n                expected = self.calibrations[camera].resolution\n                if image.shape != (expected[1], expected[0], 3):\n                    raise ValueError(\n                        f"{camera} array has shape {image.shape}, expected "\n                        f"({expected[1]}, {expected[0]}, 3)"\n                    )\n        else:\n            raw_images = self._read_images(inputs)\n        read_ms = (time.perf_counter() - read_start) * 1000.0\n\n        use_events = self.is_cuda\n        events = []\n        if use_events:\n            events = [\n                torch.cuda.Event(enable_timing=True) for _ in range(6)\n            ]\n            events[0].record()\n        cpu_stage = time.perf_counter()\n        inputs = self._upload_inputs(raw_images)\n        if use_events:\n            events[1].record()\n            upload_ms_cpu = 0.0\n        else:\n            upload_ms_cpu = (time.perf_counter() - cpu_stage) * 1000.0\n\n        cpu_stage = time.perf_counter()\n        warped = self.F.grid_sample(\n            inputs,\n            self.grid,\n            mode="bilinear",\n            padding_mode="zeros",\n            align_corners=True,\n        )\n        if use_events:\n            events[2].record()\n            remap_ms_cpu = 0.0\n        else:\n            remap_ms_cpu = (time.perf_counter() - cpu_stage) * 1000.0\n\n        cpu_stage = time.perf_counter()\n        corrected = self._apply_exposure(warped)\n        if use_events:\n            events[3].record()\n            exposure_ms_cpu = 0.0\n        else:\n            exposure_ms_cpu = (\n                time.perf_counter() - cpu_stage\n            ) * 1000.0\n\n        seam_start = time.perf_counter()\n        scheduled = self.frame_index % self.seam_update_interval == 0\n        should_check = (\n            self.paths is None\n            or scheduled\n            or self.frame_index % self.seam_check_interval == 0\n        )\n        if should_check:\n            before_residuals, score_before = self._seam_residuals(\n                corrected\n            )\n        else:\n            before_residuals = self.last_residuals\n            score_before = self.last_seam_score\n        quality_triggered = (\n            self.paths is not None\n            and should_check\n            and np.isfinite(score_before)\n            and score_before > self.seam_quality_trigger\n        )\n        seam_updated = self.paths is None or scheduled or quality_triggered\n        if seam_updated:\n            corrected_host = self._download_corrected(corrected)\n            self.weights, self.paths = multiseam.dynamic_seam_weights(\n                corrected_host,\n                self.masks,\n                self.seams,\n                self.reference_owner,\n                self.coverage,\n                self.seam_band_half_width,\n                self.seam_feather_px,\n                self.seam_max_step,\n                self.seam_center_prior,\n                self.paths,\n                self.seam_temporal_prior,\n                self.seam_temporal_max_shift_px,\n                0,\n                0.0,\n            )\n            self._cache_paths()\n            self._upload_weights(self.weights)\n            after_residuals, score_after = self._seam_residuals(\n                corrected\n            )\n        else:\n            after_residuals = before_residuals\n            score_after = score_before\n        self.last_residuals = after_residuals\n        self.last_seam_score = score_after\n        seam_ms = (time.perf_counter() - seam_start) * 1000.0\n\n        cpu_stage = time.perf_counter()\n        if use_events:\n            events[4].record()\n        panorama_tensor = self._blend(corrected)\n        if use_events:\n            events[5].record()\n            blend_ms_cpu = 0.0\n        else:\n            blend_ms_cpu = (time.perf_counter() - cpu_stage) * 1000.0\n\n        download_start = time.perf_counter()\n        panorama: Any\n        if download_output:\n            panorama = (\n                panorama_tensor.permute(1, 2, 0)\n                .contiguous()\n                .cpu()\n                .numpy()\n            )\n        else:\n            panorama = panorama_tensor\n            if self.is_cuda:\n                torch.cuda.synchronize()\n        download_ms = (time.perf_counter() - download_start) * 1000.0\n\n        if use_events:\n            torch.cuda.synchronize()\n            upload_ms = float(events[0].elapsed_time(events[1]))\n            remap_ms = float(events[1].elapsed_time(events[2]))\n            exposure_ms = float(events[2].elapsed_time(events[3]))\n            blend_ms = float(events[4].elapsed_time(events[5]))\n        else:\n            upload_ms = upload_ms_cpu\n            remap_ms = remap_ms_cpu\n            exposure_ms = exposure_ms_cpu\n            blend_ms = blend_ms_cpu\n\n        total_ms = (time.perf_counter() - total_start) * 1000.0\n        diagnostics = CudaRuntimeDiagnostics(\n            timestamp=0.0,\n            backend=self.backend,\n            precision=self.precision,\n            seam_updated=seam_updated,\n            quality_triggered=quality_triggered,\n            seam_score_before=score_before,\n            seam_score_after=score_after,\n            read_ms=read_ms,\n            upload_ms=upload_ms,\n            remap_ms=remap_ms,\n            exposure_ms=exposure_ms,\n            seam_ms=seam_ms,\n            blend_ms=blend_ms,\n            download_ms=download_ms,\n            write_ms=0.0,\n            total_ms=total_ms,\n            max_sync_gap_ms=0.0,\n        )\n        self.frame_index += 1\n        return panorama, diagnostics, after_residuals\n\n\ndef cpu_diagnostics(\n    diagnostics: realtime.RuntimeDiagnostics,\n) -> CudaRuntimeDiagnostics:\n    return CudaRuntimeDiagnostics(\n        timestamp=diagnostics.timestamp,\n        backend="cpu-reference",\n        precision="fp32",\n        seam_updated=diagnostics.seam_updated,\n        quality_triggered=diagnostics.quality_triggered,\n        seam_score_before=diagnostics.seam_score_before,\n        seam_score_after=diagnostics.seam_score_after,\n        read_ms=diagnostics.read_ms,\n        upload_ms=0.0,\n        remap_ms=diagnostics.remap_ms,\n        exposure_ms=diagnostics.exposure_ms,\n        seam_ms=diagnostics.seam_ms,\n        blend_ms=diagnostics.blend_ms,\n        download_ms=0.0,\n        write_ms=diagnostics.write_ms,\n        total_ms=diagnostics.total_ms,\n        max_sync_gap_ms=diagnostics.max_sync_gap_ms,\n    )\n\n\ndef build_parser() -> argparse.ArgumentParser:\n    parser = realtime.build_parser()\n    parser.description = __doc__\n    parser.set_defaults(\n        output_dir=DEFAULT_OUTPUT_DIR,\n        exposure_update_interval=30,\n        seam_update_interval=30,\n    )\n    parser.add_argument(\n        "--device",\n        choices=("auto", "cuda", "cpu", "torch-cpu"),\n        default="auto",\n        help=(\n            "auto selects CUDA when available and otherwise uses the CPU "\n            "reference; torch-cpu is only for numerical validation."\n        ),\n    )\n    parser.add_argument(\n        "--precision",\n        choices=("fp16", "fp32"),\n        default="fp16",\n        help="CUDA arithmetic precision; fp16 is recommended on Orin NX.",\n    )\n    parser.add_argument(\n        "--seam-check-interval",\n        type=int,\n        default=5,\n        help="Evaluate the cached seam quality every N frames on the GPU.",\n    )\n    parser.add_argument(\n        "--exposure-sample-stride",\n        type=int,\n        default=4,\n        help="Spatial stride used by the low-rate GPU exposure estimator.",\n    )\n    parser.add_argument(\n        "--benchmark-gpu-resident",\n        action="store_true",\n        help=(\n            "With --benchmark-only, leave the panorama on the GPU to measure "\n            "a downstream GPU-perception pipeline without device-to-host copy."\n        ),\n    )\n    parser.add_argument(\n        "--warmup-frames",\n        type=int,\n        default=5,\n        help="Exclude this many initial frames from the printed timing summary.",\n    )\n    parser.add_argument(\n        "--erp-width",\n        type=int,\n        default=1280,\n        help="ERP output width; the paper benchmark uses 1280.",\n    )\n    parser.add_argument(\n        "--erp-height",\n        type=int,\n        default=640,\n        help="ERP output height; the paper benchmark uses 640.",\n    )\n    parser.add_argument(\n        "--report-path",\n        type=Path,\n        help="Optional per-frame CSV, including in --benchmark-only mode.",\n    )\n    parser.add_argument(\n        "--check-cuda",\n        action="store_true",\n        help="Print PyTorch/CUDA device information and exit.",\n    )\n    return parser\n\n\ndef validate_cuda_args(args: argparse.Namespace) -> None:\n    realtime.validate_args(args)\n    if args.seam_check_interval <= 0:\n        raise ValueError("--seam-check-interval must be positive")\n    if args.exposure_sample_stride <= 0:\n        raise ValueError("--exposure-sample-stride must be positive")\n    if args.warmup_frames < 0:\n        raise ValueError("--warmup-frames must be non-negative")\n    if args.erp_width <= 0 or args.erp_height <= 0:\n        raise ValueError("ERP dimensions must be positive")\n    if args.erp_width != 2 * args.erp_height:\n        raise ValueError("ERP output must keep a 2:1 width-to-height ratio")\n    if args.benchmark_gpu_resident and not args.benchmark_only:\n        raise ValueError(\n            "--benchmark-gpu-resident requires --benchmark-only"\n        )\n\n\ndef main() -> None:\n    args = build_parser().parse_args()\n    if args.check_cuda:\n        torch = import_torch()\n        print(json.dumps(cuda_summary(torch), indent=2, ensure_ascii=False))\n        if args.device == "cuda" and not torch.cuda.is_available():\n            raise RuntimeError("CUDA device check failed")\n        return\n    validate_cuda_args(args)\n    # The projection modules read these values when LUTs are constructed.\n    base.PANO_WIDTH = int(args.erp_width)\n    base.PANO_HEIGHT = int(args.erp_height)\n    backend, torch, device = resolve_backend(args.device)\n\n    input_mapping = base.load_topic_to_camera(\n        args.cam_mapping.resolve() if args.cam_mapping else None\n    )\n    calibration_mapping = base.load_topic_to_camera(\n        args.calib_topic_mapping.resolve()\n        if args.calib_topic_mapping\n        else None\n    )\n    calibrations, calibration_sources = (\n        realtime.load_discovered_calibrations(\n            args.calib_dir.resolve(), calibration_mapping\n        )\n    )\n    realtime.validate_extrinsics(calibrations)\n    refinement = (\n        adaptive.load_refinement(args.refinement_path.resolve())\n        if args.refinement_path\n        else None\n    )\n    static_chroma_gains = adaptive.load_static_chroma_gains(\n        args.color_calibration_path.resolve()\n    )\n    indices = base.build_image_indices(\n        args.input_dir.resolve(), input_mapping\n    )\n    synchronized = base.synchronize_frames(indices, args.max_sync_gap)\n    selected = realtime.select_frames(\n        synchronized,\n        args.timestamps,\n        args.start_timestamp,\n        args.end_timestamp,\n        args.max_frames,\n        args.stride,\n    )\n    if not selected:\n        raise RuntimeError("No synchronized four-camera frames selected")\n\n    output_dir = args.output_dir.resolve()\n    if not args.benchmark_only:\n        output_dir.mkdir(parents=True, exist_ok=True)\n\n    if backend == "cpu-reference":\n        stitcher: Any = realtime.OrinRealtimeStitcher(\n            calibrations=calibrations,\n            refinement=refinement,\n            valid_radius_scale=args.valid_radius_scale,\n            exposure_update_interval=args.exposure_update_interval,\n            exposure_smoothing_alpha=args.exposure_smoothing_alpha,\n            static_chroma_gains=static_chroma_gains,\n            seam_update_interval=args.seam_update_interval,\n            seam_quality_trigger=args.seam_quality_trigger,\n            seam_band_half_width=args.seam_band_half_width,\n            seam_feather_px=args.seam_feather_px,\n            seam_max_step=args.seam_max_step,\n            seam_center_prior=args.seam_center_prior,\n            seam_temporal_prior=args.seam_temporal_prior,\n            seam_temporal_max_shift_px=args.seam_temporal_max_shift_px,\n            exposure_compensation=not args.no_exposure_compensation,\n            blend_mode=args.blend_mode,\n            wide_seam_feather_px=args.wide_seam_feather_px,\n            low_frequency_sigma_px=args.low_frequency_sigma_px,\n        )\n        cuda_info: Optional[Dict[str, object]] = None\n    else:\n        assert torch is not None and device is not None\n        stitcher = TorchPanoramaStitcher(\n            torch=torch,\n            device=device,\n            calibrations=calibrations,\n            refinement=refinement,\n            valid_radius_scale=args.valid_radius_scale,\n            exposure_update_interval=args.exposure_update_interval,\n            exposure_smoothing_alpha=args.exposure_smoothing_alpha,\n            exposure_sample_stride=args.exposure_sample_stride,\n            static_chroma_gains=static_chroma_gains,\n            seam_update_interval=args.seam_update_interval,\n            seam_check_interval=args.seam_check_interval,\n            seam_quality_trigger=args.seam_quality_trigger,\n            seam_band_half_width=args.seam_band_half_width,\n            seam_feather_px=args.seam_feather_px,\n            seam_max_step=args.seam_max_step,\n            seam_center_prior=args.seam_center_prior,\n            seam_temporal_prior=args.seam_temporal_prior,\n            seam_temporal_max_shift_px=args.seam_temporal_max_shift_px,\n            exposure_compensation=not args.no_exposure_compensation,\n            blend_mode=args.blend_mode,\n            wide_seam_feather_px=args.wide_seam_feather_px,\n            low_frequency_sigma_px=args.low_frequency_sigma_px,\n            precision=args.precision,\n        )\n        cuda_info = cuda_summary(torch)\n\n    manifest = {\n        "backend": backend,\n        "precision": (\n            stitcher.precision\n            if isinstance(stitcher, TorchPanoramaStitcher)\n            else "fp32"\n        ),\n        "cuda": cuda_info,\n        "input_dir": str(args.input_dir.resolve()),\n        "input_mapping": input_mapping,\n        "calib_dir": str(args.calib_dir.resolve()),\n        "calibration_mapping": calibration_mapping,\n        "calibration_sources": {\n            camera: str(path)\n            for camera, path in calibration_sources.items()\n        },\n        "refinement_path": (\n            str(args.refinement_path.resolve())\n            if args.refinement_path\n            else None\n        ),\n        "valid_radius_scale": args.valid_radius_scale,\n        "selected_frames": len(selected),\n        "exposure_update_interval": args.exposure_update_interval,\n        "seam_update_interval": args.seam_update_interval,\n        "seam_check_interval": args.seam_check_interval,\n        "blend_mode": args.blend_mode,\n        "erp_size": [args.erp_width, args.erp_height],\n    }\n    if not args.benchmark_only:\n        with (output_dir / "run_manifest.json").open(\n            "w", encoding="utf-8"\n        ) as handle:\n            json.dump(manifest, handle, indent=2, ensure_ascii=False)\n\n    print(f"Backend: {backend}")\n    if cuda_info and cuda_info.get("cuda_available"):\n        print(\n            f"CUDA device: {cuda_info.get(\'device_name\')} "\n            f"(CC {cuda_info.get(\'compute_capability\')}, "\n            f"{cuda_info.get(\'total_memory_mib\')} MiB)"\n        )\n    print("Calibration assignment:")\n    for camera in base.CAMERA_ORDER:\n        print(f"  {camera}: {calibration_sources[camera].name}")\n    print(\n        f"Selected {len(selected)}/{len(synchronized)} synchronized frames; "\n        f"refinement={\'enabled\' if refinement is not None else \'disabled\'}"\n    )\n\n    rows = []\n    wall_start = time.perf_counter()\n    for index, frame in enumerate(selected, start=1):\n        if isinstance(stitcher, TorchPanoramaStitcher):\n            download_output = not (\n                args.benchmark_only and args.benchmark_gpu_resident\n            )\n            panorama, diagnostic, residuals = stitcher.process(\n                frame.files, download_output=download_output\n            )\n        else:\n            panorama, cpu_diagnostic, residuals = stitcher.process(\n                frame.files\n            )\n            diagnostic = cpu_diagnostics(cpu_diagnostic)\n        diagnostic.timestamp = frame.timestamp\n        diagnostic.max_sync_gap_ms = frame.max_sync_gap * 1000.0\n        if not args.benchmark_only:\n            if panorama is None:\n                raise RuntimeError("Panorama download was unexpectedly skipped")\n            write_start = time.perf_counter()\n            path = output_dir / f"pano_{frame.timestamp:.6f}.jpg"\n            success = cv2.imwrite(\n                str(path),\n                panorama,\n                [cv2.IMWRITE_JPEG_QUALITY, args.jpeg_quality],\n            )\n            if not success:\n                raise RuntimeError(f"Failed to write {path}")\n            diagnostic.write_ms = (\n                time.perf_counter() - write_start\n            ) * 1000.0\n            diagnostic.total_ms += diagnostic.write_ms\n        row = asdict(diagnostic)\n        row["seam_residuals"] = json.dumps(\n            residuals, ensure_ascii=False, allow_nan=True\n        )\n        rows.append(row)\n        print(\n            f"[{index}/{len(selected)}] {frame.timestamp:.6f}: "\n            f"{diagnostic.total_ms:.1f} ms, "\n            f"seam_update={int(diagnostic.seam_updated)}, "\n            f"score={diagnostic.seam_score_after:.2f}"\n        )\n\n    wall_seconds = time.perf_counter() - wall_start\n    warmup = min(args.warmup_frames, max(0, len(rows) - 1))\n    timed_rows = rows[warmup:]\n    total_values = np.asarray(\n        [float(row["total_ms"]) for row in timed_rows],\n        dtype=np.float64,\n    )\n    timed_seconds = float(np.sum(total_values)) / 1000.0\n    print(\n        f"Processed {len(rows)} frames in {wall_seconds:.2f} s; "\n        f"timing summary excludes {warmup} warmup frame(s): "\n        f"mean={float(np.mean(total_values)):.1f} ms, "\n        f"median={float(np.median(total_values)):.1f} ms, "\n        f"p95={float(np.quantile(total_values, 0.95)):.1f} ms, "\n        f"pipeline={len(timed_rows) / max(timed_seconds, 1e-9):.2f} fps"\n    )\n    report_path = args.report_path.resolve() if args.report_path else None\n    if report_path is None and not args.benchmark_only:\n        report_path = output_dir / "realtime_report.csv"\n    if report_path is not None:\n        report_path.parent.mkdir(parents=True, exist_ok=True)\n        with report_path.open(\n            "w", newline="", encoding="utf-8"\n        ) as handle:\n            writer = csv.DictWriter(\n                handle, fieldnames=rows[0].keys()\n            )\n            writer.writeheader()\n            writer.writerows(rows)\n        print(f"Saved report: {report_path}")\n\n\n', 'stitch_new_uav_orin_cuda.py', "exec"), cuda_impl_namespace, cuda_impl_namespace)
